INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('c0bb27b8-2b77-59b2-a458-dc972c47b1aa', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'competency', 'AI4K12 1-A-iii.3-5, 3-5, objective', 'Explain how images are represented digitally in a computer.', '5fc18712-0a5e-56b2-80ea-fc670bdc2c2e', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-1-a-iii-3-5-lo","human_coding_scheme":"1-A-iii.3-5.LO","kind":"LO","band":"3-5","definition":"Explain how images are represented digitally in a computer.","alignment_state":"aligned","aligned_stages":[{"stage_id":"f63a89a8-8a27-5cd6-acdf-7ed9f179442b","stage":"C1:6-8 Encoding Text, Images and Numbers","relation":"broader","strength":"strong","why":"No 6-8 item covers image encoding. The 3-5 item asks how an image is stored as numbers. The stage encodes a small image in binary with a stated scheme, so it covers the item and adds text and a comparison of encodings.","sense_differs":null,"adjacent_band":true}],"citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"computer-science","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
