INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('8b5e0a9c-da81-55b9-aea3-f3195130cca1', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'competency', 'AI4K12 1-A-iii.6-8, 6-8, understanding', 'Sounds are digitally encoded by sampling the waveform at discrete points (typically several thousand samples per second), yielding a series of numbers.', '5fc18712-0a5e-56b2-80ea-fc670bdc2c2e', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-1-a-iii-6-8-eu","human_coding_scheme":"1-A-iii.6-8.EU","kind":"EU","band":"6-8","definition":"Sounds are digitally encoded by sampling the waveform at discrete points (typically several thousand samples per second), yielding a series of numbers.","alignment_state":"gap","aligned_stages":[],"gap_note":"Sound stored as samples of a waveform. C1:6-8 encodes text and images and could add sampling a sound into a series of numbers.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"computer-science","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('dc16ba4a-977a-5c15-91d4-d512e00b0cf6', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'competency', 'AI4K12 1-A-iii.6-8, 6-8, objective', 'Explain how sounds are represented digitally in a computer.', '5fc18712-0a5e-56b2-80ea-fc670bdc2c2e', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-1-a-iii-6-8-lo","human_coding_scheme":"1-A-iii.6-8.LO","kind":"LO","band":"6-8","definition":"Explain how sounds are represented digitally in a computer.","alignment_state":"aligned","aligned_stages":[{"stage_id":"f63a89a8-8a27-5cd6-acdf-7ed9f179442b","stage":"C1:6-8 Encoding Text, Images and Numbers","relation":"related","strength":"weak","why":"The item asks how sound becomes numbers by sampling. The stage has no sound and names no sampling rate. The shared idea is that media are stored as numbers, which the stage teaches for text and images.","sense_differs":"AI4K12 files encoding under sensing, as the way a machine takes in the world. The stage treats encoding as a scheme chosen for stored data.","adjacent_band":false}],"citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"computer-science","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
