INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('1ac7c9b8-2010-530a-9c5b-4a6dcdaa4862', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'competency', 'AI4K12 1-B-ii.6-8, 6-8, objective', 'Illustrate the concept of feature extraction from images by simulating an edge detector.', 'd9744903-4fda-546e-ba24-bddddc0ff5ef', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-1-b-ii-6-8-lo","human_coding_scheme":"1-B-ii.6-8.LO","kind":"LO","band":"6-8","definition":"Illustrate the concept of feature extraction from images by simulating an edge detector.","alignment_state":"gap","aligned_stages":[],"gap_note":"Simulating an edge detector on pixels. C1:6-8 or C2:6-8 could add a small program that finds features in an image from pixel values.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"computer-science","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('94eab506-155c-5a3a-83da-43dde00eedc1', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'competency', 'AI4K12 2-A-i.3-5, 3-5, objective', 'Demonstrate how different styles of map capture different aspects of the world.', '7a89e358-f18b-50d3-9c3e-9d55d50b4f4f', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-2-a-i-3-5-lo","human_coding_scheme":"2-A-i.3-5.LO","kind":"LO","band":"3-5","definition":"Demonstrate how different styles of map capture different aspects of the world.","alignment_state":"aligned","aligned_stages":[{"stage_id":"f95b2dff-2e43-597e-b8c6-a1857c0f60c7","stage":"C1:3-5 Recording and Charting Data","relation":"related","strength":"weak","why":"The stage asks what a chart leaves out. The item has children show how different map styles capture different aspects of the world. Both teach that a representation keeps some things and drops others. The stage compares no styles.","sense_differs":"The item is about maps of places. The stage is about charts of measured data, a different kind of representation.","adjacent_band":false},{"stage_id":"71bc5265-fbcd-5e5a-b093-399a24bce44d","stage":"C3:3-5 Models and Simulations of Everyday Systems","relation":"related","strength":"weak","why":"The stage has children build a model with named parts and say one thing it leaves out. The item shows that different map styles capture different aspects. Both teach that a representation keeps some things and drops others. The stage compares no styles.","sense_differs":"The item is about maps of places. The stage''s model is something that can be run and observed over time.","adjacent_band":false}],"citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"computer-science","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
