INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('04397001-90ae-59f7-845c-dbfb14deb040', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'competency', 'AI4K12 2-A-ii.9-12, 9-12, understanding', 'Syllogisms represent statements about categories and instances in a way that allows computers to derive new knowledge from existing knowledge by following simple inference rules.', 'ce5da01e-3e30-5d54-afb6-2cc94d0f9926', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-2-a-ii-9-12-eu","human_coding_scheme":"2-A-ii.9-12.EU","kind":"EU","band":"9-12","definition":"Syllogisms represent statements about categories and instances in a way that allows computers to derive new knowledge from existing knowledge by following simple inference rules.","alignment_state":"gap","aligned_stages":[],"gap_note":"Statements written in logical notation so that a program derives new facts by inference rules. C1:9-12 or C2:9-12 could add rule-based derivation.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"computer-science","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('8c16c5a1-5120-57d0-9505-00cdeb972938', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'competency', 'AI4K12 2-A-ii.K-2, K-2, objective', 'Give examples of symbols you encounter in daily life.', 'ce5da01e-3e30-5d54-afb6-2cc94d0f9926', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-2-a-ii-k-2-lo","human_coding_scheme":"2-A-ii.K-2.LO","kind":"LO","band":"K-2","definition":"Give examples of symbols you encounter in daily life.","alignment_state":"aligned","aligned_stages":[{"stage_id":"528aba11-45e9-5ec4-b5da-4ddf071ff6a2","stage":"C1:K-2 Sorting, Labelling and Symbols","relation":"broader","strength":"strong","why":"The stage has children say what an arrow, icon or letter stands for. The item asks for examples of symbols met in daily life. Both treat a symbol as something that stands for an idea.","sense_differs":null,"adjacent_band":false}],"citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"computer-science","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role)
VALUES ('bac697ab-febe-5111-a5bd-f266b8b2d837', '528aba11-45e9-5ec4-b5da-4ddf071ff6a2', '8c16c5a1-5120-57d0-9505-00cdeb972938', 'broader-strong') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('445bc407-c9e1-58c9-b1c0-d013d5a1f0b5', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'competency', 'AI4K12 2-A-iii.3-5, 3-5, understanding', 'A tree is a collection of labeled nodes, each of which (save the root) has a link to a parent node above it in the hierarchy. Childless nodes are called leaves or terminal nodes; those with children are non-terminal nodes.', '5ea454e7-77ec-5304-87e3-1a2ce51f1fc5', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-2-a-iii-3-5-eu","human_coding_scheme":"2-A-iii.3-5.EU","kind":"EU","band":"3-5","definition":"A tree is a collection of labeled nodes, each of which (save the root) has a link to a parent node above it in the hierarchy. Childless nodes are called leaves or terminal nodes; those with children are non-terminal nodes.","alignment_state":"gap","aligned_stages":[],"gap_note":"Trees as labelled nodes with parent links. No stage teaches tree structures. C1:3-5 could grow to cover them as a way to organise data.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"computer-science","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('2a1a6693-7396-556b-a5ff-e61177908f30', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'competency', 'AI4K12 2-A-iii.6-8, 6-8, understanding', 'A graph is a collection of labeled nodes connected by labeled links. Every link has a source node and a target node; every node has a set of incoming links and a set of outgoing links. Trees are a special case of graphs.', '5ea454e7-77ec-5304-87e3-1a2ce51f1fc5', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-2-a-iii-6-8-eu","human_coding_scheme":"2-A-iii.6-8.EU","kind":"EU","band":"6-8","definition":"A graph is a collection of labeled nodes connected by labeled links. Every link has a source node and a target node; every node has a set of incoming links and a set of outgoing links. Trees are a special case of graphs.","alignment_state":"gap","aligned_stages":[],"gap_note":"Graphs as labelled nodes and links. No stage covers graphs. C1:6-8 could add them as a representation next to encodings.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"computer-science","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('5ccea3f7-a5d6-5d72-8d6f-ae46a8a074b2', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'competency', 'AI4K12 2-A-iii.9-12, 9-12, understanding', 'A schema specifies the attributes of the concept being described, and its relationships to other concepts, e.g., the Restaurant schema inherits properties from the FoodEstablishment schema.', '5ea454e7-77ec-5304-87e3-1a2ce51f1fc5', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-2-a-iii-9-12-eu","human_coding_scheme":"2-A-iii.9-12.EU","kind":"EU","band":"9-12","definition":"A schema specifies the attributes of the concept being described, and its relationships to other concepts, e.g., the Restaurant schema inherits properties from the FoodEstablishment schema.","alignment_state":"gap","aligned_stages":[],"gap_note":"Schemas that list attributes and inherited properties, used in knowledge graphs. C1:9-12 could add structured records with inheritance as a data representation.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"computer-science","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('f0611a35-f3c9-5e6b-b159-4947843568ec', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'competency', 'AI4K12 2-A-iv.3-5, 3-5, objective', 'Construct a feature vector representation for a set of objects and show how similar objects are close together in feature space.', 'ade808b2-695b-521c-ae2c-97c8d0d94606', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-2-a-iv-3-5-lo","human_coding_scheme":"2-A-iv.3-5.LO","kind":"LO","band":"3-5","definition":"Construct a feature vector representation for a set of objects and show how similar objects are close together in feature space.","alignment_state":"aligned","aligned_stages":[{"stage_id":"f95b2dff-2e43-597e-b8c6-a1857c0f60c7","stage":"C1:3-5 Recording and Charting Data","relation":"related","strength":"weak","why":"The stage records measurements in a table. The item builds a row of values for each object and compares objects by closeness. The table is the same structure. The stage does not compare closeness.","sense_differs":null,"adjacent_band":false}],"citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"computer-science","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role)
VALUES ('bac697ab-febe-5111-a5bd-f266b8b2d837', 'f95b2dff-2e43-597e-b8c6-a1857c0f60c7', 'f0611a35-f3c9-5e6b-b159-4947843568ec', 'related-weak') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('19ce56d2-8566-5451-8885-0cd1cb560e5c', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'competency', 'AI4K12 2-A-iv.6-8, 6-8, objective', 'Explain how word embeddings (which are feature vectors) represent words as sequences of numbers.', 'ade808b2-695b-521c-ae2c-97c8d0d94606', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-2-a-iv-6-8-lo","human_coding_scheme":"2-A-iv.6-8.LO","kind":"LO","band":"6-8","definition":"Explain how word embeddings (which are feature vectors) represent words as sequences of numbers.","alignment_state":"gap","aligned_stages":[],"gap_note":"Embeddings are numbers chosen so that words of similar meaning sit close together. C1:6-8 encodes text as character codes, which carry no meaning. A further encoding could show the difference between the two.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"computer-science","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('be4e5d13-b6b8-5084-b419-d0c8c3aa8278', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'competency', 'AI4K12 2-A-iv.K-2, K-2, objective', 'Identify the features that make each object in a collection unique, and create a table of features to organize the objects.', 'ade808b2-695b-521c-ae2c-97c8d0d94606', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-2-a-iv-k-2-lo","human_coding_scheme":"2-A-iv.K-2.LO","kind":"LO","band":"K-2","definition":"Identify the features that make each object in a collection unique, and create a table of features to organize the objects.","alignment_state":"aligned","aligned_stages":[{"stage_id":"528aba11-45e9-5ec4-b5da-4ddf071ff6a2","stage":"C1:K-2 Sorting, Labelling and Symbols","relation":"related","strength":"weak","why":"The stage sorts objects by one property and names it. The item asks children to find what makes each object unique and to tabulate it. Only the idea of describing objects by what they have is shared.","sense_differs":"AI4K12 features are values a computer can reason about. The stage says property and sorts by one at a time. It builds no feature table.","adjacent_band":false}],"citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"computer-science","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role)
VALUES ('bac697ab-febe-5111-a5bd-f266b8b2d837', '528aba11-45e9-5ec4-b5da-4ddf071ff6a2', 'be4e5d13-b6b8-5084-b419-d0c8c3aa8278', 'related-weak') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('9da5c00f-5c22-564c-855a-bd331a81a6c5', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'competency', 'AI4K12 2-B-i.3-5, 3-5, objective', 'Illustrate how a computer can represent the playing of a game such as tic-tac-toe or nim by drawing the linear sequence of board positions produced by the players'' moves.', '941fa62b-c912-5347-9f3b-37bf0de91f4c', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-2-b-i-3-5-lo","human_coding_scheme":"2-B-i.3-5.LO","kind":"LO","band":"3-5","definition":"Illustrate how a computer can represent the playing of a game such as tic-tac-toe or nim by drawing the linear sequence of board positions produced by the players'' moves.","alignment_state":"aligned","aligned_stages":[{"stage_id":"8c7bc083-021f-5891-b502-de2f708a1e09","stage":"C2:3-5 Sequences, Loops and Conditions","relation":"related","strength":"weak","why":"The item draws the sequence of board positions a game produces. The stage traces the values a program stores at each step. Both follow how the stored condition of a system changes step by step.","sense_differs":"In the item, state is a board position in a game. The stage uses state for any values a program stores.","adjacent_band":false},{"stage_id":"71bc5265-fbcd-5e5a-b093-399a24bce44d","stage":"C3:3-5 Models and Simulations of Everyday Systems","relation":"related","strength":"weak","why":"The item draws the sequence of states a game goes through. The stage runs a simulation and records what happens over time. Both follow a system through a sequence of states. The item uses game boards. The stage uses a pond or a queue.","sense_differs":null,"adjacent_band":false}],"citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"computer-science","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role)
VALUES ('bac697ab-febe-5111-a5bd-f266b8b2d837', '8c7bc083-021f-5891-b502-de2f708a1e09', '9da5c00f-5c22-564c-855a-bd331a81a6c5', 'related-weak') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role)
VALUES ('bac697ab-febe-5111-a5bd-f266b8b2d837', '71bc5265-fbcd-5e5a-b093-399a24bce44d', '9da5c00f-5c22-564c-855a-bd331a81a6c5', 'related-weak') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('c19ab831-b08b-5d77-bbfc-33ffbbe4e119', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'competency', 'AI4K12 2-B-i.6-8, 6-8, understanding', 'Computers solve mazes, find driving routes, and reason about concepts in knowledge graphs using graph search algorithms, which construct search trees.', '941fa62b-c912-5347-9f3b-37bf0de91f4c', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-2-b-i-6-8-eu","human_coding_scheme":"2-B-i.6-8.EU","kind":"EU","band":"6-8","definition":"Computers solve mazes, find driving routes, and reason about concepts in knowledge graphs using graph search algorithms, which construct search trees.","alignment_state":"gap","aligned_stages":[],"gap_note":"Graph search for mazes and routes builds a search tree. Search appears only at C3:9-12. C2:6-8 or C3:6-8 could add a small search program.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"computer-science","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('4be20276-1dc1-50e5-817e-ef5c10b86a30', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'competency', 'AI4K12 2-B-i.9-12, 9-12, understanding', 'Computers can solve many types of problems using search techniques if the problem can be described in terms of finding a path from a start state to a goal state.', '941fa62b-c912-5347-9f3b-37bf0de91f4c', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-2-b-i-9-12-eu","human_coding_scheme":"2-B-i.9-12.EU","kind":"EU","band":"9-12","definition":"Computers can solve many types of problems using search techniques if the problem can be described in terms of finding a path from a start state to a goal state.","alignment_state":"aligned","aligned_stages":[{"stage_id":"e6374470-9533-570e-8d98-0e5b24060f4d","stage":"C3:9-12 Machine Learning, Search and Distributed Systems Compared","relation":"related","strength":"weak","why":"The item says search solves problems written as a path from a start state to a goal state. The stage names search on an objective as one of three methods to compare. Problem formulation, the item''s content, is absent from the stage.","sense_differs":"The item''s search finds a path of states to a goal. The stage''s search explores candidates and keeps those that score higher on an objective, so it also covers optimisation.","adjacent_band":false}],"citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"computer-science","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role)
VALUES ('bac697ab-febe-5111-a5bd-f266b8b2d837', 'e6374470-9533-570e-8d98-0e5b24060f4d', '4be20276-1dc1-50e5-817e-ef5c10b86a30', 'related-weak') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('bad31be2-2c67-5c6e-a425-66c674c461cf', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'competency', 'AI4K12 2-B-ii.3-5, 3-5, objective', 'Given a state of a game such as tic-tac-toe or nim, draw a search tree showing all possible next moves and their resulting states, and pick the best next move.', 'dec69566-3097-5a34-a46a-d3cb3e3b32ae', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-2-b-ii-3-5-lo","human_coding_scheme":"2-B-ii.3-5.LO","kind":"LO","band":"3-5","definition":"Given a state of a game such as tic-tac-toe or nim, draw a search tree showing all possible next moves and their resulting states, and pick the best next move.","alignment_state":"gap","aligned_stages":[],"gap_note":"Drawing every possible next move in a simple game and picking the best. C2:3-5 or C3:3-5 could add this as a program that explores options.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"computer-science","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('b00b06ca-fa6d-5e01-916e-3b382097eb7f', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'competency', 'AI4K12 2-B-ii.9-12, 9-12, understanding', 'There are multiple algorithms for generating a search tree, each with its own advantages.', 'dec69566-3097-5a34-a46a-d3cb3e3b32ae', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-2-b-ii-9-12-eu","human_coding_scheme":"2-B-ii.9-12.EU","kind":"EU","band":"9-12","definition":"There are multiple algorithms for generating a search tree, each with its own advantages.","alignment_state":"aligned","aligned_stages":[{"stage_id":"06ca57c6-f90e-5354-84b4-ee88dd292147","stage":"C2:9-12 Correctness and Efficiency","relation":"related","strength":"weak","why":"The item says several algorithms can build a search tree, each with its own advantages. The stage compares algorithms for any task on step counts and names no search task. Both weigh one algorithm against another.","sense_differs":"AI4K12 algorithms here build search trees over states. The stage compares any algorithms on how steps grow with input. Search through a list would be a different sense of search.","adjacent_band":false}],"citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"computer-science","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role)
VALUES ('bac697ab-febe-5111-a5bd-f266b8b2d837', '06ca57c6-f90e-5354-84b4-ee88dd292147', 'b00b06ca-fa6d-5e01-916e-3b382097eb7f', 'related-weak') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('4455f7e6-bcf1-5f89-a003-96d7a7e113b4', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'competency', 'AI4K12 2-B-ii.9-12, 9-12, objective', 'Illustrate breadth-first, depth-first, and best-first search algorithms to grow a search tree for a graph search problem.', 'dec69566-3097-5a34-a46a-d3cb3e3b32ae', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-2-b-ii-9-12-lo","human_coding_scheme":"2-B-ii.9-12.LO","kind":"LO","band":"9-12","definition":"Illustrate breadth-first, depth-first, and best-first search algorithms to grow a search tree for a graph search problem.","alignment_state":"gap","aligned_stages":[],"gap_note":"Breadth-first, depth-first and best-first search growing a search tree. C3:9-12 names Search and teaches no search method. Best-first search scores candidates, which fits the space''s own definition.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"computer-science","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('978775f7-7def-5193-bf0a-c0b620f64276', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'competency', 'AI4K12 2-C-i.3-5, 3-5, understanding', 'Classification problems assign each input to one of a predetermined set of classes. Search problems construct answers by applying operators to states to generate new states.', 'cee27363-2809-5dee-97e8-07d9349500df', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-2-c-i-3-5-eu","human_coding_scheme":"2-C-i.3-5.EU","kind":"EU","band":"3-5","definition":"Classification problems assign each input to one of a predetermined set of classes. Search problems construct answers by applying operators to states to generate new states.","alignment_state":"gap","aligned_stages":[],"gap_note":"Sorting problems into classification and search problems. C3:3-5 could add this when it compares what systems do with data.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"computer-science","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('c1f33aee-9769-5ded-aaf0-51da5445f2f2', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'competency', 'AI4K12 2-C-i.6-8, 6-8, understanding', 'Prediction problems are similar to classification problems except they estimate a continuous value, such as height or daily temperature. Sequential decision problems choose the next move for any given state in order to maximize overall reward.', 'cee27363-2809-5dee-97e8-07d9349500df', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-2-c-i-6-8-eu","human_coding_scheme":"2-C-i.6-8.EU","kind":"EU","band":"6-8","definition":"Prediction problems are similar to classification problems except they estimate a continuous value, such as height or daily temperature. Sequential decision problems choose the next move for any given state in order to maximize overall reward.","alignment_state":"gap","aligned_stages":[],"gap_note":"Prediction and sequential decision problems alongside classification and search. C3:6-8 could add a way to name the kind of task a model performs.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"computer-science","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('20c276a5-4b30-57b0-98f5-236d41574310', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'competency', 'AI4K12 2-C-i.9-12, 9-12, understanding', 'Reasoning problems can be categorized based on the types of inputs supplied, the types of outputs to be produced, and the characteristics of the search space, if applicable.', 'cee27363-2809-5dee-97e8-07d9349500df', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-2-c-i-9-12-eu","human_coding_scheme":"2-C-i.9-12.EU","kind":"EU","band":"9-12","definition":"Reasoning problems can be categorized based on the types of inputs supplied, the types of outputs to be produced, and the characteristics of the search space, if applicable.","alignment_state":"aligned","aligned_stages":[{"stage_id":"e6374470-9533-570e-8d98-0e5b24060f4d","stage":"C3:9-12 Machine Learning, Search and Distributed Systems Compared","relation":"related","strength":"weak","why":"The item sorts reasoning problems by input, output and search space. The stage compares three kinds of system on what each needs as input and what each guarantees. Both ask what goes in and what comes out. They sort different things.","sense_differs":"AI4K12 sorts problems such as classification, prediction and search. The stage sorts kinds of system: machine learning, search and distributed systems. Distributed systems have no AI4K12 counterpart.","adjacent_band":false}],"citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"computer-science","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role)
VALUES ('bac697ab-febe-5111-a5bd-f266b8b2d837', 'e6374470-9533-570e-8d98-0e5b24060f4d', '20c276a5-4b30-57b0-98f5-236d41574310', 'related-weak') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('6619ee35-40af-52af-b5e8-48bf8ea57c2f', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'competency', 'AI4K12 2-C-ii.3-5, 3-5, objective', 'Describe the differences between two algorithms for classifying things: decision trees, or neural networks like Teachable Machine.', '378ba33c-ede0-5143-862f-48af30bab0a5', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-2-c-ii-3-5-lo","human_coding_scheme":"2-C-ii.3-5.LO","kind":"LO","band":"3-5","definition":"Describe the differences between two algorithms for classifying things: decision trees, or neural networks like Teachable Machine.","alignment_state":"gap","aligned_stages":[],"gap_note":"Comparing a decision tree with a neural network as two ways to classify. Computational-Core compares methods only at C3:9-12.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"computer-science","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('75682b34-c6ff-592c-acbf-2e0e6fef9478', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'competency', 'AI4K12 2-C-ii.9-12, 9-12, understanding', 'AI includes a wide variety of reasoning algorithms for solving different types of reasoning problems. Some use symbolic representations (e.g., search trees) while others are numerical in nature (e.g., neural nets operating on feature vectors).', '378ba33c-ede0-5143-862f-48af30bab0a5', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-2-c-ii-9-12-eu","human_coding_scheme":"2-C-ii.9-12.EU","kind":"EU","band":"9-12","definition":"AI includes a wide variety of reasoning algorithms for solving different types of reasoning problems. Some use symbolic representations (e.g., search trees) while others are numerical in nature (e.g., neural nets operating on feature vectors).","alignment_state":"aligned","aligned_stages":[{"stage_id":"06ca57c6-f90e-5354-84b4-ee88dd292147","stage":"C2:9-12 Correctness and Efficiency","relation":"related","strength":"weak","why":"The item says different reasoning problems call for different algorithms. The stage chooses between algorithms for a stated need and justifies the choice. Both tie the choice of algorithm to the problem.","sense_differs":"AI4K12 reasoning algorithms solve classification, search or inference problems. The stage compares algorithms for any task on how many steps they take.","adjacent_band":false}],"citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"computer-science","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role)
VALUES ('bac697ab-febe-5111-a5bd-f266b8b2d837', '06ca57c6-f90e-5354-84b4-ee88dd292147', '75682b34-c6ff-592c-acbf-2e0e6fef9478', 'related-weak') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('bc7aa35c-6877-5295-b1e4-759923ca92c8', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'competency', 'AI4K12 3-A-i.9-12, 9-12, understanding', 'Both supervised and unsupervised learning algorithms find patterns in data. Supervised learning uses features to predict the class label supplied by a teacher; unsupervised learning groups similar instances together, creating its own classes. Reinforcement learning uses trial and error to find a policy for choosing actions that maximizes the reinforcement signal.', '311d76ca-7e55-5a47-a08b-d114e3801305', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-3-a-i-9-12-eu","human_coding_scheme":"3-A-i.9-12.EU","kind":"EU","band":"9-12","definition":"Both supervised and unsupervised learning algorithms find patterns in data. Supervised learning uses features to predict the class label supplied by a teacher; unsupervised learning groups similar instances together, creating its own classes. Reinforcement learning uses trial and error to find a policy for choosing actions that maximizes the reinforcement signal.","alignment_state":"aligned","aligned_stages":[{"stage_id":"e6374470-9533-570e-8d98-0e5b24060f4d","stage":"C3:9-12 Machine Learning, Search and Distributed Systems Compared","relation":"related","strength":"weak","why":"The item says supervised and unsupervised learning find patterns in data and reinforcement learning uses trial and error. The stage describes machine learning as parameter adjustment from data. It does not separate the three kinds of learning.","sense_differs":"The item compares machine learning with human learning. The stage describes only the machine procedure and attributes no intention. The alignment rests on the machine side.","adjacent_band":false}],"citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"computer-science","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role)
VALUES ('bac697ab-febe-5111-a5bd-f266b8b2d837', 'e6374470-9533-570e-8d98-0e5b24060f4d', 'bc7aa35c-6877-5295-b1e4-759923ca92c8', 'related-weak') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('e7b4d5c5-7ae9-5b49-8d77-07d149f938f1', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'competency', 'AI4K12 3-A-ii.3-5, 3-5, objective', 'Model how supervised learning identifies patterns in labeled data.', '716d51ab-c2a1-54fe-8f8d-eebb98b7c965', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-3-a-ii-3-5-lo","human_coding_scheme":"3-A-ii.3-5.LO","kind":"LO","band":"3-5","definition":"Model how supervised learning identifies patterns in labeled data.","alignment_state":"gap","aligned_stages":[],"gap_note":"Modelling how supervised learning finds patterns in labelled data. Machine learning enters Computational-Core only at C3:9-12. C3:3-5 or C3:6-8 could add a hands-on version.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"computer-science","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('d4c61496-9330-524c-a47c-394b9668c543', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'competency', 'AI4K12 3-A-ii.6-8, 6-8, understanding', 'Unsupervised learning is useful when we don''t know in advance what classes exist. It discovers patterns (or classes) in data by grouping nearby points into clusters.', '716d51ab-c2a1-54fe-8f8d-eebb98b7c965', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-3-a-ii-6-8-eu","human_coding_scheme":"3-A-ii.6-8.EU","kind":"EU","band":"6-8","definition":"Unsupervised learning is useful when we don''t know in advance what classes exist. It discovers patterns (or classes) in data by grouping nearby points into clusters.","alignment_state":"gap","aligned_stages":[],"gap_note":"Unsupervised learning groups nearby points into clusters. No stage covers clustering. C3:6-8 could add it next to feedback models.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"computer-science","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('7892570b-8ea8-5ffd-b44f-70685a5f18cb', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'competency', 'AI4K12 3-A-ii.9-12, 9-12, objective', 'Model how machine learning constructs a reasoner for classification or prediction by adjusting the reasoner''s parameters (its internal representations).', '716d51ab-c2a1-54fe-8f8d-eebb98b7c965', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-3-a-ii-9-12-lo","human_coding_scheme":"3-A-ii.9-12.LO","kind":"LO","band":"9-12","definition":"Model how machine learning constructs a reasoner for classification or prediction by adjusting the reasoner''s parameters (its internal representations).","alignment_state":"aligned","aligned_stages":[{"stage_id":"e6374470-9533-570e-8d98-0e5b24060f4d","stage":"C3:9-12 Machine Learning, Search and Distributed Systems Compared","relation":"same","strength":"strong","why":"The stage describes how machine learning adjusts parameters from data to improve a measured result. The item models how a reasoner is built by adjusting its parameters. The matching enduring understanding adds that a person selects the model in advance.","sense_differs":"AI4K12 speaks of learning and a reasoner. The stage keeps both as a parameter-adjusting procedure and attributes no understanding to the machine.","adjacent_band":false}],"citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"computer-science","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role)
VALUES ('bac697ab-febe-5111-a5bd-f266b8b2d837', 'e6374470-9533-570e-8d98-0e5b24060f4d', '7892570b-8ea8-5ffd-b44f-70685a5f18cb', 'same-strong') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('73d2fdc2-d658-5ea2-a69a-ba54d7658845', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'competency', 'AI4K12 3-A-iii.3-5, 3-5, objective', 'Train a classification model using machine learning, and then examine the accuracy of the model on new inputs.', '81655d66-4764-5e12-b686-dfcb62fe022a', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-3-a-iii-3-5-lo","human_coding_scheme":"3-A-iii.3-5.LO","kind":"LO","band":"3-5","definition":"Train a classification model using machine learning, and then examine the accuracy of the model on new inputs.","alignment_state":"gap","aligned_stages":[],"gap_note":"Training a classifier and checking its accuracy on new inputs. No stage below C3:9-12 trains a model.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"computer-science","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('72fb35a8-d636-5f17-b424-e667e71575a8', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'competency', 'AI4K12 3-A-iii.6-8, 6-8, objective', 'Train and evaluate a classification or prediction model using machine learning on a tabular dataset.', '81655d66-4764-5e12-b686-dfcb62fe022a', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-3-a-iii-6-8-lo","human_coding_scheme":"3-A-iii.6-8.LO","kind":"LO","band":"6-8","definition":"Train and evaluate a classification or prediction model using machine learning on a tabular dataset.","alignment_state":"gap","aligned_stages":[],"gap_note":"Training and evaluating a model on a tabular dataset. It connects to the C1 data tables. C3:6-8 could grow to cover it.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"computer-science","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('e41a0449-8a1f-55ee-8994-07bd5931fd22', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'competency', 'AI4K12 3-A-iii.9-12, 9-12, objective', 'Use either a supervised or unsupervised learning algorithm to train a model on real world data, then evaluate the results.', '81655d66-4764-5e12-b686-dfcb62fe022a', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-3-a-iii-9-12-lo","human_coding_scheme":"3-A-iii.9-12.LO","kind":"LO","band":"9-12","definition":"Use either a supervised or unsupervised learning algorithm to train a model on real world data, then evaluate the results.","alignment_state":"gap","aligned_stages":[],"gap_note":"Train a model on data and evaluate the result. C3:9-12 describes parameter adjustment and has no indicator for training or evaluating. Covers the evaluation idea that the dropped C2:6-8 match claimed.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"computer-science","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('c009e958-eb0e-5209-a224-07ff33a86f48', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'competency', 'AI4K12 3-A-iv.6-8, 6-8, understanding', 'Machine learning algorithms use labeled training data to construct reasoning models that do classification or prediction. Once training is complete, the reasoning model can be applied to new data to solve problems or make decisions.', 'cd131703-7c1f-533d-8069-aa6b27bbeca1', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-3-a-iv-6-8-eu","human_coding_scheme":"3-A-iv.6-8.EU","kind":"EU","band":"6-8","definition":"Machine learning algorithms use labeled training data to construct reasoning models that do classification or prediction. Once training is complete, the reasoning model can be applied to new data to solve problems or make decisions.","alignment_state":"gap","aligned_stages":[],"gap_note":"Training builds a reasoning model and using it applies the model to new data. Computational-Core does not yet separate these two phases.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"computer-science","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('311f13ed-9f70-5fab-b4c7-452121b32de9', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'competency', 'AI4K12 3-A-iv.9-12, 9-12, understanding', 'The steps are: deciding what problem you want to solve, figuring out where you will obtain the training data, choosing a feature set, figuring out how to label the data, running the learning algorithm, use of a cross-validation set to decide when training should stop, and using a test set to measure performance.', 'cd131703-7c1f-533d-8069-aa6b27bbeca1', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-3-a-iv-9-12-eu","human_coding_scheme":"3-A-iv.9-12.EU","kind":"EU","band":"9-12","definition":"The steps are: deciding what problem you want to solve, figuring out where you will obtain the training data, choosing a feature set, figuring out how to label the data, running the learning algorithm, use of a cross-validation set to decide when training should stop, and using a test set to measure performance.","alignment_state":"gap","aligned_stages":[],"gap_note":"Steps of building a classifier: source the data, choose features, label, run learning, stop on a validation set, measure on a test set. C3:9-12 says what machine learning is and teaches no build or check steps.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"computer-science","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('b1003ab0-395a-5807-9f3f-7bcd951f8987', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'competency', 'AI4K12 3-A-v.6-8, 6-8, understanding', 'In decision tree learning, each step adds a new node, which tests a single feature value. In neural network learning, each step makes a small change to every weight in the network.', '211fadbf-4f63-5f51-964f-98750f75ed57', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-3-a-v-6-8-eu","human_coding_scheme":"3-A-v.6-8.EU","kind":"EU","band":"6-8","definition":"In decision tree learning, each step adds a new node, which tests a single feature value. In neural network learning, each step makes a small change to every weight in the network.","alignment_state":"gap","aligned_stages":[],"gap_note":"Decision tree learning adds nodes and neural network learning changes weights. C3:9-12 mentions adjusting parameters but names no specific method.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"computer-science","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('99ab2779-474f-576b-92e8-dd1461f36d2a', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'competency', 'AI4K12 3-A-vi.3-5, 3-5, understanding', 'Computers can learn from experience if there is a "reinforcement" signal indicating whether the computer''s actions are leading to good or bad outcomes.', '3e8f84b2-2780-523b-a258-af252517b548', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-3-a-vi-3-5-eu","human_coding_scheme":"3-A-vi.3-5.EU","kind":"EU","band":"3-5","definition":"Computers can learn from experience if there is a \"reinforcement\" signal indicating whether the computer''s actions are leading to good or bad outcomes.","alignment_state":"gap","aligned_stages":[],"gap_note":"A reinforcement signal lets a computer learn from trial and error. No stage covers a reward signal. C3:3-5 or C3:6-8 could connect it to Feedback.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"computer-science","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('948bbff1-ceeb-54a4-b4f4-4465cd4bc233', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'competency', 'AI4K12 3-B-i.6-8, 6-8, understanding', 'Neural networks are organized as layers of units (input, hidden, and output layers), with weighted connections between units in successive layers.', 'a4f2e0ae-e4dc-58a0-bf32-047b6c2d1753', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-3-b-i-6-8-eu","human_coding_scheme":"3-B-i.6-8.EU","kind":"EU","band":"6-8","definition":"Neural networks are organized as layers of units (input, hidden, and output layers), with weighted connections between units in successive layers.","alignment_state":"gap","aligned_stages":[],"gap_note":"Neural networks as layers of units with weighted connections. No stage describes this structure. C3:6-8 or C3:9-12 could add it as one model structure.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"computer-science","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('6af8acb2-4999-5ea8-b1df-53f65790c27f', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'competency', 'AI4K12 3-B-ii.6-8, 6-8, understanding', 'During training, weights are adjusted in response to errors in the network''s output, so that an error will be less likely when the input is seen again.', 'd5f6da80-28e9-5796-9b9b-446a1a346d2a', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-3-b-ii-6-8-eu","human_coding_scheme":"3-B-ii.6-8.EU","kind":"EU","band":"6-8","definition":"During training, weights are adjusted in response to errors in the network''s output, so that an error will be less likely when the input is seen again.","alignment_state":"aligned","aligned_stages":[{"stage_id":"45c484c9-e753-5bb3-86af-086bc28fce31","stage":"C3:6-8 Agent-Based and Feedback Models","relation":"related","strength":"weak","why":"The item says weights change in response to errors in the output. The stage identifies a feedback loop in a model. The error signal in training is one case of output returned to change later behaviour. The stage has no training or weights.","sense_differs":"In the item, feedback is an error signal used at each training step. In the stage the loop runs inside the model as agents act and the pattern changes.","adjacent_band":false}],"citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"computer-science","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role)
VALUES ('bac697ab-febe-5111-a5bd-f266b8b2d837', '45c484c9-e753-5bb3-86af-086bc28fce31', '6af8acb2-4999-5ea8-b1df-53f65790c27f', 'related-weak') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('462b17fa-2c6f-51bb-9903-3f409e5b4a54', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'competency', 'AI4K12 3-C-i.6-8, 6-8, understanding', 'The choice of features to include, and the best encoding to use for these features, depends on the particular reasoning problem we are trying to solve.', '423760ec-8eea-566c-b637-86a64899d95e', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-3-c-i-6-8-eu","human_coding_scheme":"3-C-i.6-8.EU","kind":"EU","band":"6-8","definition":"The choice of features to include, and the best encoding to use for these features, depends on the particular reasoning problem we are trying to solve.","alignment_state":"aligned","aligned_stages":[{"stage_id":"f63a89a8-8a27-5cd6-acdf-7ed9f179442b","stage":"C1:6-8 Encoding Text, Images and Numbers","relation":"related","strength":"weak","why":"The item says the best encoding of features depends on the problem. The stage compares two encodings of the same data on size and kept detail. Both show that an encoding choice changes what can be done with the data.","sense_differs":"In AI4K12 encoding means how a feature value is written for a classifier. In the stage it means a binary scheme for text, an image or numbers.","adjacent_band":false}],"citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"computer-science","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role)
VALUES ('bac697ab-febe-5111-a5bd-f266b8b2d837', 'f63a89a8-8a27-5cd6-acdf-7ed9f179442b', '462b17fa-2c6f-51bb-9903-3f409e5b4a54', 'related-weak') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('8e570e2f-fb6a-538f-b0c8-e4db3e017c98', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'competency', 'AI4K12 3-C-i.9-12, 9-12, understanding', 'Humans decide which features to include in a dataset and how to encode them. This can have consequences for machine learning algorithms trained on these datasets.', '423760ec-8eea-566c-b637-86a64899d95e', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-3-c-i-9-12-eu","human_coding_scheme":"3-C-i.9-12.EU","kind":"EU","band":"9-12","definition":"Humans decide which features to include in a dataset and how to encode them. This can have consequences for machine learning algorithms trained on these datasets.","alignment_state":"aligned","aligned_stages":[{"stage_id":"22e68923-d1f7-54a7-9cb5-6a3591c04a02","stage":"C1:9-12 Information, Compression and the Limits of Representation","relation":"related","strength":"weak","why":"The item says people decide which features go into a dataset and how to encode them, with consequences downstream. The stage names a limit of a representation and its effect on a result. The overlap is the effect of an encoding choice.","sense_differs":"The item concerns features in a machine learning dataset. The stage concerns limits such as precision or size in any representation. AI4K12 has no item on information in bits or compression.","adjacent_band":false}],"citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"computer-science","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role)
VALUES ('bac697ab-febe-5111-a5bd-f266b8b2d837', '22e68923-d1f7-54a7-9cb5-6a3591c04a02', '8e570e2f-fb6a-538f-b0c8-e4db3e017c98', 'related-weak') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('9853dd93-786d-532a-9808-b0cec81d5c9d', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'competency', 'AI4K12 3-C-i.K-2, K-2, objective', 'Create a labeled dataset with explicit features to illustrate how computers can learn to classify things like foods, movies, or toys.', '423760ec-8eea-566c-b637-86a64899d95e', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-3-c-i-k-2-lo","human_coding_scheme":"3-C-i.K-2.LO","kind":"LO","band":"K-2","definition":"Create a labeled dataset with explicit features to illustrate how computers can learn to classify things like foods, movies, or toys.","alignment_state":"aligned","aligned_stages":[{"stage_id":"528aba11-45e9-5ec4-b5da-4ddf071ff6a2","stage":"C1:K-2 Sorting, Labelling and Symbols","relation":"related","strength":"weak","why":"The stage has children label each group with a word or picture. The item has children create a labelled dataset with features. Labelling groups is a first step toward a labelled dataset, but the stage builds no dataset for a computer.","sense_differs":"In AI4K12 a label is a class name that a computer learns to predict. In the stage a label names a group that a child made.","adjacent_band":false}],"citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"computer-science","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role)
VALUES ('bac697ab-febe-5111-a5bd-f266b8b2d837', '528aba11-45e9-5ec4-b5da-4ddf071ff6a2', '9853dd93-786d-532a-9808-b0cec81d5c9d', 'related-weak') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('c147b725-3b24-578b-8d57-4173a6037413', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'competency', 'AI4K12 3-C-ii.6-8, 6-8, understanding', 'Machine learning requires large amounts of data to be effective. Human expertise is usually required to label the data, which could be labor intensive.', 'a168f816-c218-5542-ac05-dda663475a70', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-3-c-ii-6-8-eu","human_coding_scheme":"3-C-ii.6-8.EU","kind":"EU","band":"6-8","definition":"Machine learning requires large amounts of data to be effective. Human expertise is usually required to label the data, which could be labor intensive.","alignment_state":"gap","aligned_stages":[],"gap_note":"Machine learning needs large amounts of labelled data, and labelling takes labour. Technical need for data only. C3:9-12 could state it as a condition of Machine Learning.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"computer-science","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('89d0d879-4177-5165-97f7-286bfd1541c0', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'competency', 'AI4K12 3-C-iii.6-8, 6-8, understanding', 'Bias can result if the model is asked to classify inputs that don''t resemble the training data, or if the training data contains irrelevant correlations we don''t want the classifier to rely on.', '601869a4-2d86-5435-9f86-2ca8402cde8a', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-3-c-iii-6-8-eu","human_coding_scheme":"3-C-iii.6-8.EU","kind":"EU","band":"6-8","definition":"Bias can result if the model is asked to classify inputs that don''t resemble the training data, or if the training data contains irrelevant correlations we don''t want the classifier to rely on.","alignment_state":"gap","aligned_stages":[],"gap_note":"Technical core only: a model misbehaves on inputs unlike its training data or when the data hold irrelevant correlations. C3:9-12 could state this as a limit of Machine Learning.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"computer-science","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('03a77945-b5db-5f3e-bd8d-0b145a24ad71', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'competency', 'AI4K12 3-C-iii.9-12, 9-12, understanding', 'Machine learning algorithms will take advantage of any imbalances or correlations in the training set that help lower the error rate. If the dataset is not representative, those correlations can be misleading.', '601869a4-2d86-5435-9f86-2ca8402cde8a', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-3-c-iii-9-12-eu","human_coding_scheme":"3-C-iii.9-12.EU","kind":"EU","band":"9-12","definition":"Machine learning algorithms will take advantage of any imbalances or correlations in the training set that help lower the error rate. If the dataset is not representative, those correlations can be misleading.","alignment_state":"gap","aligned_stages":[],"gap_note":"Technical core only: learning algorithms exploit imbalances and correlations in the training set, and an unrepresentative set makes those correlations misleading. C3:9-12 states no data limit of machine learning.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"computer-science","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('623a8be1-b78a-5ab9-9aa9-73aa7b16d83b', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'competency', 'AI4K12 3-C-iii.K-2, K-2, understanding', 'How well a computer learns to classify depends on the data used to train it.', '601869a4-2d86-5435-9f86-2ca8402cde8a', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-3-c-iii-k-2-eu","human_coding_scheme":"3-C-iii.K-2.EU","kind":"EU","band":"K-2","definition":"How well a computer learns to classify depends on the data used to train it.","alignment_state":"gap","aligned_stages":[],"gap_note":"Technical core only: how well a computer classifies depends on its training data. Machine learning enters Computational-Core at C3:9-12, so an earlier stage would first need a classifier example.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"computer-science","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('52428d65-25b3-57c7-85d2-684da9033de9', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'competency', 'AI4K12 4-A-iv.9-12, 9-12, understanding', 'Simple NLP approaches include keyword matching, dictionary lookup, and template matching, while newer, more sophisticated but less transparent approaches use deep neural networks and machine learning.', 'da15a18d-c573-564a-982b-5a704c9b462c', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-4-a-iv-9-12-eu","human_coding_scheme":"4-A-iv.9-12.EU","kind":"EU","band":"9-12","definition":"Simple NLP approaches include keyword matching, dictionary lookup, and template matching, while newer, more sophisticated but less transparent approaches use deep neural networks and machine learning.","alignment_state":"gap","aligned_stages":[],"gap_note":"Technical core only: simple methods such as keyword and template matching compared with learned methods on what each can guarantee. C2:9-12 or C3:9-12 could host the comparison with language as the example.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"computer-science","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('e688af73-bc95-5145-bcaf-cb73a64ebf2b', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'competency', 'AI4K12 4-A-iv.K-2, K-2, understanding', 'Intelligent assistants (e.g., Siri, Alexa) are computers designed to respond to a limited set of requests. They cannot engage in a conversation like a human.', 'da15a18d-c573-564a-982b-5a704c9b462c', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-4-a-iv-k-2-eu","human_coding_scheme":"4-A-iv.K-2.EU","kind":"EU","band":"K-2","definition":"Intelligent assistants (e.g., Siri, Alexa) are computers designed to respond to a limited set of requests. They cannot engage in a conversation like a human.","alignment_state":"aligned","aligned_stages":[{"stage_id":"04edbe9b-292d-5101-a009-fc46ead81427","stage":"C3:K-2 Machines Follow Rules People Write","relation":"related","strength":"weak","why":"The item says intelligent assistants respond to a limited set of requests. The stage asks for a machine doing exactly what its instructions say and what happens when they are wrong. Both tie a machine''s behaviour to how it was set up.","sense_differs":"Technical core only: a device answers only the requests its program was built for. Intelligent in the item names a class of devices. The stage avoids the word.","adjacent_band":false}],"citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"computer-science","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
