INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('7cbe05dd-828c-5b43-a156-a5fab17ee554', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'competency', 'AI4K12 4-D-i.K-2, K-2, understanding', 'Artificial Intelligence devices are not people, they are computer programs designed by people.', '5ca98c0a-a273-5319-a534-3a3328354663', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-4-d-i-k-2-eu","human_coding_scheme":"4-D-i.K-2.EU","kind":"EU","band":"K-2","definition":"Artificial Intelligence devices are not people, they are computer programs designed by people.","alignment_state":"aligned","aligned_stages":[{"stage_id":"04edbe9b-292d-5101-a009-fc46ead81427","stage":"C3:K-2 Machines Follow Rules People Write","relation":"narrower","strength":"partial","why":"The stage has children say who wrote a machine''s rules and show a machine doing exactly what its instructions say. That meets the clause that AI devices are programs designed by people. The stage does not address the clause about people.","sense_differs":"The item sits under philosophy of mind. The alignment rests on the technical core only: a device runs a program that people wrote. The stage says nothing about understanding or about AI devices in particular.","adjacent_band":false}],"citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"computer-science","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
