UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('ai4k12_alignment', '[{"competencybase_id":"OE-COMPETENCY-ai4k12-3-c-i","human_coding_scheme":"3-C-i","relation":"broader","why":"AI4K12 handles data in its Datasets rows: feature sets for training and large training sets. Computational-Core''s Data is wider. It covers any recorded values that stand for something, from sorted objects to charted measurements."},{"competencybase_id":"OE-COMPETENCY-ai4k12-3-c-ii","human_coding_scheme":"3-C-ii","relation":"broader","why":"AI4K12 handles data in its Datasets rows: feature sets for training and large training sets. Computational-Core''s Data is wider. It covers any recorded values that stand for something, from sorted objects to charted measurements."}]'::jsonb) WHERE id = 'e49e585b-b47d-553f-adff-0381568f4589';
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('ai4k12_alignment', '[{"competencybase_id":"OE-COMPETENCY-ai4k12-2-a-i","human_coding_scheme":"2-A-i","relation":"broader","why":"Computational-Core''s Representation names any structure that stands for something and can be stored or processed. In principle that includes the five AI4K12 rows. The stages teach only symbols, tables, charts and binary encodings."},{"competencybase_id":"OE-COMPETENCY-ai4k12-2-a-ii","human_coding_scheme":"2-A-ii","relation":"broader","why":"Computational-Core''s Representation names any structure that stands for something and can be stored or processed. In principle that includes the five AI4K12 rows. The stages teach only symbols, tables, charts and binary encodings."},{"competencybase_id":"OE-COMPETENCY-ai4k12-2-a-iii","human_coding_scheme":"2-A-iii","relation":"broader","why":"Computational-Core''s Representation names any structure that stands for something and can be stored or processed. In principle that includes the five AI4K12 rows. The stages teach only symbols, tables, charts and binary encodings."},{"competencybase_id":"OE-COMPETENCY-ai4k12-2-a-iv","human_coding_scheme":"2-A-iv","relation":"broader","why":"Computational-Core''s Representation names any structure that stands for something and can be stored or processed. In principle that includes the five AI4K12 rows. The stages teach only symbols, tables, charts and binary encodings."},{"competencybase_id":"OE-COMPETENCY-ai4k12-1-a-iii","human_coding_scheme":"1-A-iii","relation":"broader","why":"Computational-Core''s Representation names any structure that stands for something and can be stored or processed. In principle that includes the five AI4K12 rows. The stages teach only symbols, tables, charts and binary encodings."}]'::jsonb) WHERE id = '6fe408fb-82b8-5eb7-84a5-eecf93c7946f';
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('ai4k12_alignment', '[{"competencybase_id":"OE-COMPETENCY-ai4k12-2-a-i","human_coding_scheme":"2-A-i","relation":"related","why":"Only the Representation (Abstraction) row matches: a map keeps some aspects and drops others, which is hiding detail. The two pipeline rows use abstraction for levels of processing from signal to meaning, which is a different sense."},{"competencybase_id":"OE-COMPETENCY-ai4k12-1-b-iii","human_coding_scheme":"1-B-iii","relation":"related","why":"Only the Representation (Abstraction) row matches: a map keeps some aspects and drops others, which is hiding detail. The two pipeline rows use abstraction for levels of processing from signal to meaning, which is a different sense."},{"competencybase_id":"OE-COMPETENCY-ai4k12-1-b-iv","human_coding_scheme":"1-B-iv","relation":"related","why":"Only the Representation (Abstraction) row matches: a map keeps some aspects and drops others, which is hiding detail. The two pipeline rows use abstraction for levels of processing from signal to meaning, which is a different sense."}]'::jsonb) WHERE id = '5dc1875c-652e-5a9e-a1eb-c15e52549e17';
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('ai4k12_alignment', '[{"competencybase_id":"OE-COMPETENCY-ai4k12-2-c-ii","human_coding_scheme":"2-C-ii","relation":"broader","why":"AI4K12 names reasoning algorithms and search algorithms. Computational-Core''s Algorithm is any finite sequence of steps that turns input into output, so these two are special cases."},{"competencybase_id":"OE-COMPETENCY-ai4k12-2-b-ii","human_coding_scheme":"2-B-ii","relation":"broader","why":"AI4K12 names reasoning algorithms and search algorithms. Computational-Core''s Algorithm is any finite sequence of steps that turns input into output, so these two are special cases."}]'::jsonb) WHERE id = '91071763-b749-515d-a80e-f1f6d1eaf0fa';
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('ai4k12_alignment', '[{"competencybase_id":"OE-COMPETENCY-ai4k12-2-b-i","human_coding_scheme":"2-B-i","relation":"broader","why":"AI4K12 uses state for a game position or a step in a search. Computational-Core''s State is the stored values of any system at one moment, which includes a game position."}]'::jsonb) WHERE id = 'cf5195de-3352-52d0-8e04-b7fc14ede8de';
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('ai4k12_alignment', '[{"competencybase_id":"OE-COMPETENCY-ai4k12-3-a-iii","human_coding_scheme":"3-A-iii","relation":"related","why":"AI4K12 uses model for a trained mapping from inputs to outputs. Computational-Core''s Model is a simplified description of a system that is run to see what follows. The senses meet where a trained model is run on new inputs."},{"competencybase_id":"OE-COMPETENCY-ai4k12-3-a-iv","human_coding_scheme":"3-A-iv","relation":"related","why":"AI4K12 uses model for a trained mapping from inputs to outputs. Computational-Core''s Model is a simplified description of a system that is run to see what follows. The senses meet where a trained model is run on new inputs."}]'::jsonb) WHERE id = 'ea8aba67-5ef6-59cd-9f1f-6198c3966353';
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('ai4k12_alignment', '[{"competencybase_id":"OE-COMPETENCY-ai4k12-2-b-i","human_coding_scheme":"2-B-i","relation":"related","why":"AI4K12 search finds a path from a start state to a goal by growing a search tree. Computational-Core''s Search explores candidates and keeps those that score higher on an objective. The two overlap on exploring options."},{"competencybase_id":"OE-COMPETENCY-ai4k12-2-b-ii","human_coding_scheme":"2-B-ii","relation":"related","why":"AI4K12 search finds a path from a start state to a goal by growing a search tree. Computational-Core''s Search explores candidates and keeps those that score higher on an objective. The two overlap on exploring options."}]'::jsonb) WHERE id = '244aa554-5721-559e-be7e-4e3d4331e644';
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('ai4k12_alignment', '[{"competencybase_id":"OE-COMPETENCY-ai4k12-3-a-ii","human_coding_scheme":"3-A-ii","relation":"broader","why":"These AI4K12 rows cover finding patterns, training, using a trained model, adjusting internal representations, learning from experience and weight adjustment. Computational-Core''s Machine Learning, a procedure that adjusts parameters from data to improve a result, is the general idea behind them."},{"competencybase_id":"OE-COMPETENCY-ai4k12-3-a-iii","human_coding_scheme":"3-A-iii","relation":"broader","why":"These AI4K12 rows cover finding patterns, training, using a trained model, adjusting internal representations, learning from experience and weight adjustment. Computational-Core''s Machine Learning, a procedure that adjusts parameters from data to improve a result, is the general idea behind them."},{"competencybase_id":"OE-COMPETENCY-ai4k12-3-a-iv","human_coding_scheme":"3-A-iv","relation":"broader","why":"These AI4K12 rows cover finding patterns, training, using a trained model, adjusting internal representations, learning from experience and weight adjustment. Computational-Core''s Machine Learning, a procedure that adjusts parameters from data to improve a result, is the general idea behind them."},{"competencybase_id":"OE-COMPETENCY-ai4k12-3-a-v","human_coding_scheme":"3-A-v","relation":"broader","why":"These AI4K12 rows cover finding patterns, training, using a trained model, adjusting internal representations, learning from experience and weight adjustment. Computational-Core''s Machine Learning, a procedure that adjusts parameters from data to improve a result, is the general idea behind them."},{"competencybase_id":"OE-COMPETENCY-ai4k12-3-a-vi","human_coding_scheme":"3-A-vi","relation":"broader","why":"These AI4K12 rows cover finding patterns, training, using a trained model, adjusting internal representations, learning from experience and weight adjustment. Computational-Core''s Machine Learning, a procedure that adjusts parameters from data to improve a result, is the general idea behind them."},{"competencybase_id":"OE-COMPETENCY-ai4k12-3-b-ii","human_coding_scheme":"3-B-ii","relation":"broader","why":"These AI4K12 rows cover finding patterns, training, using a trained model, adjusting internal representations, learning from experience and weight adjustment. Computational-Core''s Machine Learning, a procedure that adjusts parameters from data to improve a result, is the general idea behind them."}]'::jsonb) WHERE id = '63046d12-d8d7-5830-b2df-ac2833e913f0';
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('ai4k12_alignment', '[{"competencybase_id":"OE-COMPETENCY-ai4k12-3-b-ii","human_coding_scheme":"3-B-ii","relation":"related","why":"Error signals and reinforcement signals are fed back to change later behaviour, so they are cases of feedback. In training the signal goes to the learning rule. In Computational-Core output is returned as input. AI4K12 has no row on feedback loops in models."},{"competencybase_id":"OE-COMPETENCY-ai4k12-3-a-vi","human_coding_scheme":"3-A-vi","relation":"related","why":"Error signals and reinforcement signals are fed back to change later behaviour, so they are cases of feedback. In training the signal goes to the learning rule. In Computational-Core output is returned as input. AI4K12 has no row on feedback loops in models."}]'::jsonb) WHERE id = '7024c45a-e091-5f8f-b41c-c70e70cb69c3';
UPDATE projects SET introduction = introduction || '

Alignment with AI4K12. This space is aligned with the AI4K12 progression charts (Five Big Ideas in Artificial Intelligence, held in CompetencyBase) with a narrow computer science focus: only technical content (representation, data, search, models, training, datasets and program behaviour) is aligned, and societal, ethical and cognitive items are left to the Interdisciplinary space. 10 of 12 stages align with at least one AI4K12 item of the same grade band (3 strong, 1 partial and 17 weak matches), and 28 AI4K12 items inside the focus have no stage and are listed as gaps in the taxonomy. A match was made only where a teacher could defend it. The alignments are proposed. AI drafted them and no subject expert has reviewed them.' WHERE id = 'bac697ab-febe-5111-a5bd-f266b8b2d837' AND introduction NOT LIKE '%Alignment with AI4K12. This space%';

