VALUES ('7799c335-872d-5d2a-945c-215f11436c6e', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'competency', 'AI4K12 5-C-ii: AI & The Economy (Effects on Employment)', 'AI & The Economy (Effects on Employment)', '41aff59a-c564-5ca3-9e54-34d29327af72', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-5-c-ii","human_coding_scheme":"5-C-ii","kind":"concept","band":null,"definition":"AI & The Economy (Effects on Employment)","alignment_state":"structure","aligned_stages":[],"citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"cross-domain","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('106d4b7e-703d-5014-9623-ba355efa3210', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'competency', 'AI4K12 1-A-i.3-5, 3-5, objective', 'Compare human and animal perception.', 'f49e9222-d298-5452-8f0a-52bd21b5b269', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-1-a-i-3-5-lo","human_coding_scheme":"1-A-i.3-5.LO","kind":"LO","band":"3-5","definition":"Compare human and animal perception.","alignment_state":"gap","aligned_stages":[],"gap_note":"Comparing human and animal perception. I2:3-5 compares how species act and learn, and its Agency definition includes sensing. Adding a senses comparison there would cover this item.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"cross-domain","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('39633cff-9431-5895-8001-84b472c035d1', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'competency', 'AI4K12 1-A-i.6-8, 6-8, objective', 'Give examples of how humans combine information from multiple modalities.', 'f49e9222-d298-5452-8f0a-52bd21b5b269', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-1-a-i-6-8-lo","human_coding_scheme":"1-A-i.6-8.LO","kind":"LO","band":"6-8","definition":"Give examples of how humans combine information from multiple modalities.","alignment_state":"gap","aligned_stages":[],"gap_note":"Humans combining information from several senses. The cognition sense of Information (sensory input and a receiver whose expectations change) could carry a 6-8 stage on how nervous systems and sensors combine signals.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"cross-domain","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('8ea56e14-5555-5d41-98a4-a2ecc0a4c46f', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'competency', 'AI4K12 1-A-ii.3-5, 3-5, objective', 'Illustrate how computer sensing differs from human sensing.', 'deec27c0-f6e9-5c28-8a70-aa4df0978953', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-1-a-ii-3-5-lo","human_coding_scheme":"1-A-ii.3-5.LO","kind":"LO","band":"3-5","definition":"Illustrate how computer sensing differs from human sensing.","alignment_state":"gap","aligned_stages":[],"gap_note":"Computer sensing compared with human sensing. Pair it with the item above in I2:3-5 so that animal, human and device senses sit in one comparison.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"cross-domain","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('ecfcc7aa-f46a-56fe-97c6-1a7a71acf4df', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'competency', 'AI4K12 1-A-ii.9-12, 9-12, objective', 'Describe the limitations and advantages of various types of computer sensors.', 'deec27c0-f6e9-5c28-8a70-aa4df0978953', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-1-a-ii-9-12-lo","human_coding_scheme":"1-A-ii.9-12.LO","kind":"LO","band":"9-12","definition":"Describe the limitations and advantages of various types of computer sensors.","alignment_state":"gap","aligned_stages":[],"gap_note":"Limits and advantages of computer sensors. I2:9-12 names information processing as a shared substrate. Adding sensors beside nervous systems there would cover this item.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"cross-domain","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('472994cc-973e-5ec7-a1f8-3d2bc504d260', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'competency', 'AI4K12 1-B-i.3-5, 3-5, understanding', 'Perception is the extraction of meaning from sensory signals.', '299f1283-6551-5d9f-ab14-a34a7df23aa2', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-1-b-i-3-5-eu","human_coding_scheme":"1-B-i.3-5.EU","kind":"EU","band":"3-5","definition":"Perception is the extraction of meaning from sensory signals.","alignment_state":"gap","aligned_stages":[],"gap_note":"Perception as extracting meaning from sensory signals. Information separates a cue, a signal and meaning across biology, cognition and AI. A 3-5 stage on Information could cover this.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"cross-domain","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('4f00869d-0ab5-5ed2-a867-a33d852c41a2', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'competency', 'AI4K12 1-C-i.9-12, 9-12, understanding', 'Domain knowledge in AI systems is often derived from statistics collected from millions of sentences or images.', '911fdba3-9191-513e-a2a5-8e768092bc55', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-1-c-i-9-12-eu","human_coding_scheme":"1-C-i.9-12.EU","kind":"EU","band":"9-12","definition":"Domain knowledge in AI systems is often derived from statistics collected from millions of sentences or images.","alignment_state":"gap","aligned_stages":[],"gap_note":"AI domain knowledge drawn from statistics over millions of human texts and images. I1:9-12 (Distributed Cognition, Knowledge) could add machine culture as knowledge spread across people and artifacts.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"cross-domain","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('fd2ee140-4f3a-5c19-b7bf-25998e7e922d', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'competency', 'AI4K12 1-C-ii.6-8, 6-8, objective', 'Describe how a vision system might exhibit cultural bias if it lacked knowledge of objects not found in the culture of the people who created it.', '29459c9d-a07e-5303-ac87-13594ca59725', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-1-c-ii-6-8-lo","human_coding_scheme":"1-C-ii.6-8.LO","kind":"LO","band":"6-8","definition":"Describe how a vision system might exhibit cultural bias if it lacked knowledge of objects not found in the culture of the people who created it.","alignment_state":"gap","aligned_stages":[],"gap_note":"A vision system lacking knowledge of objects from other cultures. I1:6-8 covers culture as transmitted knowledge. A case on what a system trained in one culture misses would cover it.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"cross-domain","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('ada944d5-723b-5b60-bf15-4fdce6cf70e0', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'competency', 'AI4K12 2-A-i.6-8, 6-8, objective', 'Show how a game board (e.g., tic-tac-toe, Chutes and Ladders, Monopoly, chess) can be represented by a description in plain language.', '42b6043e-0fa4-55b7-863e-e8fb7f16d580', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-2-a-i-6-8-lo","human_coding_scheme":"2-A-i.6-8.LO","kind":"LO","band":"6-8","definition":"Show how a game board (e.g., tic-tac-toe, Chutes and Ladders, Monopoly, chess) can be represented by a description in plain language.","alignment_state":"gap","aligned_stages":[],"gap_note":"Describing a game board in plain language by its essential parts. The education sense of Abstraction names this step. A 6-8 stage on Abstraction or Representation would cover it.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"cross-domain","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('d3cefb8b-4577-5c77-9ae1-f20c411f03a6', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'competency', 'AI4K12 2-A-i.K-2, K-2, understanding', 'The map is not the territory. A map is a representation of a territory.', '42b6043e-0fa4-55b7-863e-e8fb7f16d580', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-2-a-i-k-2-eu","human_coding_scheme":"2-A-i.K-2.EU","kind":"EU","band":"K-2","definition":"The map is not the territory. A map is a representation of a territory.","alignment_state":"gap","aligned_stages":[],"gap_note":"A map is a representation of a territory. Representation and Abstraction have no primary stage. A K-2 stage on maps and symbols would cover this item.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"cross-domain","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('c3f37ec9-653b-5278-a28f-3a0f1f23aaa9', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'competency', 'AI4K12 2-A-ii.K-2, K-2, objective', 'Give examples of symbols you encounter in daily life.', '1c55fbf4-64ed-5b49-8f4f-54786029a08e', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-2-a-ii-k-2-lo","human_coding_scheme":"2-A-ii.K-2.LO","kind":"LO","band":"K-2","definition":"Give examples of symbols you encounter in daily life.","alignment_state":"aligned","aligned_stages":[{"stage_id":"9fc65a59-5de1-51ad-ad30-a9c0faca177a","stage":"I1:K-2 Groups, Rules, and Tools","relation":"related","strength":"weak","why":"The stage lists signs among the ways people share ideas. The item asks for symbols met in daily life. Signs are a kind of symbol, so the two share one example and little else.","sense_differs":"Both treat a sign or symbol as a stand-in. The stage frames signs as a way to tell others something. The item frames a symbol as replacing a word, with no computer use stated at this band.","adjacent_band":false}],"citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"cross-domain","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role)
VALUES ('371fce26-d1f3-439b-95df-0a0e38b8a824', '9fc65a59-5de1-51ad-ad30-a9c0faca177a', 'c3f37ec9-653b-5278-a28f-3a0f1f23aaa9', 'related-weak') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('6e628b11-e13c-5a51-bdee-57f0cdd74c2a', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'competency', 'AI4K12 2-A-iii.6-8, 6-8, understanding', 'A graph is a collection of labeled nodes connected by labeled links. Every link has a source node and a target node; every node has a set of incoming links and a set of outgoing links. Trees are a special case of graphs.', '0ee4350b-4ffe-58e3-9ffb-1fac2d3ae5b7', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-2-a-iii-6-8-eu","human_coding_scheme":"2-A-iii.6-8.EU","kind":"EU","band":"6-8","definition":"A graph is a collection of labeled nodes connected by labeled links. Every link has a source node and a target node; every node has a set of incoming links and a set of outgoing links. Trees are a special case of graphs.","alignment_state":"gap","aligned_stages":[],"gap_note":"Graphs as labeled nodes and links, with trees as a special case. Descent notes that a tree fits ancestry only partly. An I4 stage on Descent could compare trees and networks.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"cross-domain","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('9551b6d6-d4f9-5a11-b9fa-000a5f9a17a3', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'competency', 'AI4K12 2-A-iv.K-2, K-2, objective', 'Identify the features that make each object in a collection unique, and create a table of features to organize the objects.', 'd5cd9e39-74af-534d-abbc-ebc576768fbd', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-2-a-iv-k-2-lo","human_coding_scheme":"2-A-iv.K-2.LO","kind":"LO","band":"K-2","definition":"Identify the features that make each object in a collection unique, and create a table of features to organize the objects.","alignment_state":"aligned","aligned_stages":[{"stage_id":"04d57493-ac2f-5ec6-a1ba-0596eae3158a","stage":"I4:K-2 Things That Get Passed On","relation":"related","strength":"weak","why":"The stage has children notice that members of a family differ. The item has them identify the features that make each object unique and tabulate them. A table of how family members differ would meet both.","sense_differs":"In the stage, variation matters because some differences are passed on. The item lists features to describe or classify objects and has no idea of passing on.","adjacent_band":false}],"citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"cross-domain","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role)
VALUES ('371fce26-d1f3-439b-95df-0a0e38b8a824', '04d57493-ac2f-5ec6-a1ba-0596eae3158a', '9551b6d6-d4f9-5a11-b9fa-000a5f9a17a3', 'related-weak') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('fde7d7d0-82ce-5a6a-b4ad-0928430eab67', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'competency', 'AI4K12 2-B-i.6-8, 6-8, objective', 'Illustrate how a computer can solve a maze, find a route on a map, or reason about concepts in a knowledge graph by drawing a search tree.', 'fb196068-8345-559f-9dca-e21f1c2993ee', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-2-b-i-6-8-lo","human_coding_scheme":"2-B-i.6-8.LO","kind":"LO","band":"6-8","definition":"Illustrate how a computer can solve a maze, find a route on a map, or reason about concepts in a knowledge graph by drawing a search tree.","alignment_state":"aligned","aligned_stages":[{"stage_id":"d2dc3119-7af8-55d8-8bfe-b63a4ec56acb","stage":"I3:6-8 How Minds and Cultures Search for Better Ideas","relation":"related","strength":"weak","why":"The stage compares starting from a random guess with starting from the closest known example, then making small revisions. The item draws a search tree for a maze or route. Both concern moving through candidate solutions. The stage defines no states or operators.","sense_differs":"The stage describes a human habit, local search from a familiar start, with no fixed list of options. The item uses systematic graph search over defined states. One word, ''search'', covers two procedures.","adjacent_band":false}],"citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"cross-domain","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role)
VALUES ('371fce26-d1f3-439b-95df-0a0e38b8a824', 'd2dc3119-7af8-55d8-8bfe-b63a4ec56acb', 'fde7d7d0-82ce-5a6a-b4ad-0928430eab67', 'related-weak') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('a95e414f-8b6d-5b5b-9a23-1c5a63b57409', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'competency', 'AI4K12 2-B-i.9-12, 9-12, objective', 'Identify types of real-world problems that are search problems and describe their states and operators.', 'fb196068-8345-559f-9dca-e21f1c2993ee', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-2-b-i-9-12-lo","human_coding_scheme":"2-B-i.9-12.LO","kind":"LO","band":"9-12","definition":"Identify types of real-world problems that are search problems and describe their states and operators.","alignment_state":"aligned","aligned_stages":[{"stage_id":"ba60a3be-0135-5b53-b88f-a7aecfe0ed96","stage":"I3:9-12 The Shared Structure of Discovery: Darwin''s Notebooks and the History of Science","relation":"related","strength":"weak","why":"The stage explains that a search for a solution can test only ideas already generated. The full space of possible ideas stays untested. The item has students describe problems as search with states and operators. Both rest on a space of options.","sense_differs":"The stage uses search loosely for how people and science explore ideas, where the space is never fully listed. The item needs explicit states, operators and a goal, so the space is defined.","adjacent_band":false}],"citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"cross-domain","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role)
VALUES ('371fce26-d1f3-439b-95df-0a0e38b8a824', 'ba60a3be-0135-5b53-b88f-a7aecfe0ed96', 'a95e414f-8b6d-5b5b-9a23-1c5a63b57409', 'related-weak') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('160dc988-3ffc-5ee9-9667-edc0f0c6ed38', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'competency', 'AI4K12 3-A-i.3-5, 3-5, understanding', 'Both people and computers can learn by finding patterns in data, or by trial and error. But people are flexible learners who can adapt to unfamiliar situations and learn in other ways, such as by observing others, by asking questions, or by making connections to prior learning.', '79618618-e18f-5c14-bef7-68f3b676b34d', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-3-a-i-3-5-eu","human_coding_scheme":"3-A-i.3-5.EU","kind":"EU","band":"3-5","definition":"Both people and computers can learn by finding patterns in data, or by trial and error. But people are flexible learners who can adapt to unfamiliar situations and learn in other ways, such as by observing others, by asking questions, or by making connections to prior learning.","alignment_state":"aligned","aligned_stages":[{"stage_id":"31b2be29-7a8c-5f98-a447-55ecf57f1ff9","stage":"I2:3-5 Comparing How Different Living Things Act, Learn, and Teach","relation":"narrower","strength":"partial","why":"The stage asks for an animal or person learning a behavior by watching another. The item says people learn by observing others and by linking to earlier learning, while computers learn from data or trial and error. The stage covers the living half.","sense_differs":"The stage''s learning is a lasting change in behavior from experience, in a living thing. A computer''s learning adjusts numbers from example data and implies no understanding. Teaching and scaffolding have no machine counterpart here.","adjacent_band":false}],"citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"cross-domain","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role)
VALUES ('371fce26-d1f3-439b-95df-0a0e38b8a824', '31b2be29-7a8c-5f98-a447-55ecf57f1ff9', '160dc988-3ffc-5ee9-9667-edc0f0c6ed38', 'narrower-partial') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('0bb09738-2565-53a7-be84-b0d69114c0da', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'competency', 'AI4K12 3-A-i.3-5, 3-5, objective', 'Differentiate between how people learn and how computers learn.', '79618618-e18f-5c14-bef7-68f3b676b34d', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-3-a-i-3-5-lo","human_coding_scheme":"3-A-i.3-5.LO","kind":"LO","band":"3-5","definition":"Differentiate between how people learn and how computers learn.","alignment_state":"gap","aligned_stages":[],"gap_note":"Differentiate how people and computers learn. I2:3-5 covers only the living side, so this is the part of the row its aligned item leaves unmet.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"cross-domain","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('746c6616-07d6-54ad-b746-9748b3910b4b', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'competency', 'AI4K12 3-A-i.6-8, 6-8, objective', 'Contrast the unique characteristics of human learning with the ways machine learning systems operate.', '79618618-e18f-5c14-bef7-68f3b676b34d', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-3-a-i-6-8-lo","human_coding_scheme":"3-A-i.6-8.LO","kind":"LO","band":"6-8","definition":"Contrast the unique characteristics of human learning with the ways machine learning systems operate.","alignment_state":"gap","aligned_stages":[],"gap_note":"Contrasting human learning with machine learning. Learning has no 6-8 stage here. I2:6-8 or I3:6-8 could add it, using the ''does not carry over'' note on what changes in each.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"cross-domain","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('4861ad77-bb57-577d-b5ac-459140e85773', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'competency', 'AI4K12 3-A-i.9-12, 9-12, objective', 'Define supervised, unsupervised, and reinforcement learning algorithms, and give examples of human learning that are similar to each algorithm.', '79618618-e18f-5c14-bef7-68f3b676b34d', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-3-a-i-9-12-lo","human_coding_scheme":"3-A-i.9-12.LO","kind":"LO","band":"9-12","definition":"Define supervised, unsupervised, and reinforcement learning algorithms, and give examples of human learning that are similar to each algorithm.","alignment_state":"gap","aligned_stages":[],"gap_note":"Define supervised, unsupervised and reinforcement learning with human parallels. Unmet in all stages once the I2:9-12 match is dropped. I2:9-12 or I3:9-12 could add it using the Learning facets.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"cross-domain","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('e8acf160-f854-58b9-bcfc-de4931fca52f', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'competency', 'AI4K12 3-A-i.K-2, K-2, objective', 'Describe and provide examples of how people learn and how computers learn.', '79618618-e18f-5c14-bef7-68f3b676b34d', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-3-a-i-k-2-lo","human_coding_scheme":"3-A-i.K-2.LO","kind":"LO","band":"K-2","definition":"Describe and provide examples of how people learn and how computers learn.","alignment_state":"gap","aligned_stages":[],"gap_note":"How people learn and how computers learn, at K-2. Learning is primary only from I2:3-5. Adding Learning to I2:K-2 beside Development would cover it.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"cross-domain","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('6ee53cb6-b3c5-5fb3-9b79-2b573f7ccaf3', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'competency', 'AI4K12 3-A-ii.3-5, 3-5, objective', 'Model how supervised learning identifies patterns in labeled data.', 'f2829f86-3f08-50ea-a0fc-800fc8036c99', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-3-a-ii-3-5-lo","human_coding_scheme":"3-A-ii.3-5.LO","kind":"LO","band":"3-5","definition":"Model how supervised learning identifies patterns in labeled data.","alignment_state":"aligned","aligned_stages":[{"stage_id":"a64224d1-ac36-5b1c-b475-3c5af3aa4656","stage":"I3:3-5 Good Guesses, Better Guesses: Testing Ideas","relation":"related","strength":"weak","why":"In the guess-my-rule game, children test a hidden pattern with yes or no answers. The item asks students to model how supervised learning finds a pattern in labeled data. Both infer a rule from labeled examples. The stage models no machine process.","sense_differs":"Children choose their own test examples and reflect on whether they tried to confirm or refute a guess. A supervised learner fits the labeled data it is given. It does not choose examples or judge its own method.","adjacent_band":false}],"citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"cross-domain","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role)
VALUES ('371fce26-d1f3-439b-95df-0a0e38b8a824', 'a64224d1-ac36-5b1c-b475-3c5af3aa4656', '6ee53cb6-b3c5-5fb3-9b79-2b573f7ccaf3', 'related-weak') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('4a136334-6acf-522a-bedd-ccb5f814d185', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'competency', 'AI4K12 3-A-v.3-5, 3-5, understanding', 'In a decision tree learning game, the tree''s branch nodes are questions and the leaf nodes are classes.', 'e2ce234b-99df-5c3c-9d38-976dd9b6489a', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-3-a-v-3-5-eu","human_coding_scheme":"3-A-v.3-5.EU","kind":"EU","band":"3-5","definition":"In a decision tree learning game, the tree''s branch nodes are questions and the leaf nodes are classes.","alignment_state":"gap","aligned_stages":[],"gap_note":"A decision tree whose branches are questions and whose leaves are classes. The education sense of Algorithm describes a plant key built the same way. A 3-5 stage on Algorithm would cover it.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"cross-domain","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('5149bc27-c76d-5b00-93ad-582fe98845d6', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'competency', 'AI4K12 3-A-v.9-12, 9-12, objective', 'Describe how various types of machine learning algorithms learn by adjusting their internal representations.', 'e2ce234b-99df-5c3c-9d38-976dd9b6489a', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-3-a-v-9-12-lo","human_coding_scheme":"3-A-v.9-12.LO","kind":"LO","band":"9-12","definition":"Describe how various types of machine learning algorithms learn by adjusting their internal representations.","alignment_state":"aligned","aligned_stages":[{"stage_id":"396e3dd9-4f22-5160-b6c7-3752caefa1b8","stage":"I4:9-12 Selection Across Biology, Culture, Education, and AI","relation":"related","strength":"weak","why":"The stage compares biological selection with algorithmic selection such as a genetic algorithm''s fitness function. The item describes how machine learning methods improve by adjusting internal representations. Both are machine procedures that improve a score.","sense_differs":"Selection works on a population of candidates over rounds. The item''s methods adjust one model''s numbers or tree. AI4K12 does not name evolutionary algorithms, so the match covers only the improve-a-score idea.","adjacent_band":false}],"citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"cross-domain","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role)
VALUES ('371fce26-d1f3-439b-95df-0a0e38b8a824', '396e3dd9-4f22-5160-b6c7-3752caefa1b8', '5149bc27-c76d-5b00-93ad-582fe98845d6', 'related-weak') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('6180721d-889e-5ed7-a941-442002a08d84', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'competency', 'AI4K12 3-A-vi.6-8, 6-8, understanding', 'Supervised learning tells the agent what output it should produce for each input; reinforcement learning only tells the agent how well it''s doing as it chooses actions to take.', '4ae4e085-ece9-5aef-a5b2-e607a3469183', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-3-a-vi-6-8-eu","human_coding_scheme":"3-A-vi.6-8.EU","kind":"EU","band":"6-8","definition":"Supervised learning tells the agent what output it should produce for each input; reinforcement learning only tells the agent how well it''s doing as it chooses actions to take.","alignment_state":"gap","aligned_stages":[],"gap_note":"Supervised learning versus learning from reward alone. Feedback and Incentive have no stage. A 6-8 stage on Incentive across culture, biology and AI would cover it.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"cross-domain","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('e6473ea3-23d0-5a04-b8e5-0c354c66d985', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'competency', 'AI4K12 3-C-iii.3-5, 3-5, understanding', 'Machine learning algorithms require a representative collection of data in order to build an accurate model. Training datasets drawn from historical data may reflect pre-existing human and societal biases.', '844fac9b-110d-5f3f-9be4-ad4c944d7af7', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-3-c-iii-3-5-eu","human_coding_scheme":"3-C-iii.3-5.EU","kind":"EU","band":"3-5","definition":"Machine learning algorithms require a representative collection of data in order to build an accurate model. Training datasets drawn from historical data may reflect pre-existing human and societal biases.","alignment_state":"gap","aligned_stages":[],"gap_note":"Training data from history can carry past human biases. Transmission (AI sense) and Culture (machine culture) cover patterns carried forward in data. I1:6-8 could add a case.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"cross-domain","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('c34aec50-c20a-5f6a-b72c-79ff899dc888', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'competency', 'AI4K12 4-A-ii.9-12, 9-12, understanding', 'A single word can have multiple senses. People use context and world knowledge to determine the correct sense, but computers don''t typically represent meaning with this degree of subtlety.', '74e2f6c0-7ed5-50a3-8b8b-91da32abe1d6', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-4-a-ii-9-12-eu","human_coding_scheme":"4-A-ii.9-12.EU","kind":"EU","band":"9-12","definition":"A single word can have multiple senses. People use context and world knowledge to determine the correct sense, but computers don''t typically represent meaning with this degree of subtlety.","alignment_state":"gap","aligned_stages":[],"gap_note":"Computers struggle when a word has several senses. Communication (culture sense: interpretation depends on context) is the nearest concept, and I2:9-12 could add a language case. The vocabulary''s cross-domain word notes are a separate matter.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"cross-domain","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('45c82825-93c3-5156-b1aa-8e0c56841b47', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'competency', 'AI4K12 4-B-i.9-12, 9-12, understanding', 'For humans or computers to infer the meaning of a story requires understanding of cultural knowledge, naive physics, and folk psychology. This is still difficult for computers.', 'f41fcb89-6568-5bdb-9c7f-b64952a02aa9', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-4-b-i-9-12-eu","human_coding_scheme":"4-B-i.9-12.EU","kind":"EU","band":"9-12","definition":"For humans or computers to infer the meaning of a story requires understanding of cultural knowledge, naive physics, and folk psychology. This is still difficult for computers.","alignment_state":"gap","aligned_stages":[],"gap_note":"Understanding a story needs cultural knowledge, naive physics and folk psychology. Intuitive Theories at I3:9-12 could add folk physics and folk biology as what machines lack.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"cross-domain","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('6dee85fc-48c5-549c-9c78-3efec5afcf0d', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'competency', 'AI4K12 4-B-i.K-2, K-2, objective', 'Give commonsense explanations of human behavior or events that might be useful for a robot to know.', 'f41fcb89-6568-5bdb-9c7f-b64952a02aa9', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-4-b-i-k-2-lo","human_coding_scheme":"4-B-i.K-2.LO","kind":"LO","band":"K-2","definition":"Give commonsense explanations of human behavior or events that might be useful for a robot to know.","alignment_state":"aligned","aligned_stages":[{"stage_id":"8363df74-ecd8-54e9-82f1-e93623f9995c","stage":"I3:K-2 Ideas That Are Like Other Ideas","relation":"narrower","strength":"partial","why":"The stage has children explain an action by what the person wanted, such as reaching for a cup because of thirst. The item asks for commonsense explanations of human behavior. The stage covers the explaining. The item adds what a robot would need.","sense_differs":"AI4K12 frames commonsense as knowledge a computer may lack. The stage treats explaining by wants as a natural early skill in children.","adjacent_band":false}],"citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"cross-domain","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role)
VALUES ('371fce26-d1f3-439b-95df-0a0e38b8a824', '8363df74-ecd8-54e9-82f1-e93623f9995c', '6dee85fc-48c5-549c-9c78-3efec5afcf0d', 'narrower-partial') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('bc364405-3425-5512-ae95-5cb025b74368', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'competency', 'AI4K12 4-C-i.6-8, 6-8, understanding', 'Computers can recognize human emotional states by looking at facial expressions, gaze, gestures, body language, tone of voice, and choice of words.', 'c7a97bcb-89a6-5871-903a-9e4bb088f6fa', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-4-c-i-6-8-eu","human_coding_scheme":"4-C-i.6-8.EU","kind":"EU","band":"6-8","definition":"Computers can recognize human emotional states by looking at facial expressions, gaze, gestures, body language, tone of voice, and choice of words.","alignment_state":"gap","aligned_stages":[],"gap_note":"Computers recognize emotional states from face, voice and words. Communication (biology and culture: signals and cues) could feed a 6-8 stage on reading other people''s states. Theory of Mind covers goals and beliefs and adds little here.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"cross-domain","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('ed46eaa0-7c2a-58bb-bd7b-137bfa5c66db', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'competency', 'AI4K12 4-D-i.6-8, 6-8, understanding', 'The nature of consciousness is an unsolved problem, but two important criteria seem to be self-awareness and personal history.', '12ea2223-9fd7-58f2-9b4c-aa2c3f4c7ac3', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-4-d-i-6-8-eu","human_coding_scheme":"4-D-i.6-8.EU","kind":"EU","band":"6-8","definition":"The nature of consciousness is an unsolved problem, but two important criteria seem to be self-awareness and personal history.","alignment_state":"aligned","aligned_stages":[{"stage_id":"3a112595-4435-5db0-950d-ca7c6da5160d","stage":"I2:6-8 Agency, Niche Construction, and Selection","relation":"related","strength":"weak","why":"The stage defines agency without conscious intention. The item names self-awareness and personal history as criteria for consciousness in AI. The shared topic is awareness versus goal-directed behavior. The stage teaches no consciousness criteria and names no machine.","sense_differs":"The stage''s agency applies to organisms and needs no consciousness. The item asks whether machines are conscious and calls the question unsolved. Agency and consciousness are different things in both.","adjacent_band":false}],"citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"cross-domain","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role)
VALUES ('371fce26-d1f3-439b-95df-0a0e38b8a824', '3a112595-4435-5db0-950d-ca7c6da5160d', 'ed46eaa0-7c2a-58bb-bd7b-137bfa5c66db', 'related-weak') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('d16f9740-c5f6-5423-a6d7-0b39612f0e4f', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'competency', 'AI4K12 4-D-i.6-8, 6-8, objective', 'Define criteria for consciousness and evaluate AI systems or fictional AI characters according to those criteria.', '12ea2223-9fd7-58f2-9b4c-aa2c3f4c7ac3', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-4-d-i-6-8-lo","human_coding_scheme":"4-D-i.6-8.LO","kind":"LO","band":"6-8","definition":"Define criteria for consciousness and evaluate AI systems or fictional AI characters according to those criteria.","alignment_state":"gap","aligned_stages":[],"gap_note":"Evaluating AI or fictional characters against criteria for consciousness. I2:6-8 separates agency from conscious intention and could add this evaluation task.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"cross-domain","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('dc04372a-0a39-5b99-a4e5-1e37acd1de68', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'competency', 'AI4K12 4-D-i.9-12, 9-12, objective', 'Debate alternative perspectives on human vs. artificial intelligence.', '12ea2223-9fd7-58f2-9b4c-aa2c3f4c7ac3', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-4-d-i-9-12-lo","human_coding_scheme":"4-D-i.9-12.LO","kind":"LO","band":"9-12","definition":"Debate alternative perspectives on human vs. artificial intelligence.","alignment_state":"aligned","aligned_stages":[{"stage_id":"5d938d91-e81b-516c-ba58-a234b6d5559f","stage":"I2:9-12 Agency and Niche Construction Across Biological and Technological Systems","relation":"related","strength":"weak","why":"The stage ranks four organisms on an agency spectrum and analyzes one designed system. The item has students debate human versus artificial intelligence. The shared topic is how machine systems compare with living ones. The stage sets up no debate.","sense_differs":"The stage grades agency as a capacity to act toward goals, with designer-set goals for software. The item debates whether machines can match human-like intelligence, which is a different question.","adjacent_band":false}],"citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"cross-domain","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role)
VALUES ('371fce26-d1f3-439b-95df-0a0e38b8a824', '5d938d91-e81b-516c-ba58-a234b6d5559f', 'dc04372a-0a39-5b99-a4e5-1e37acd1de68', 'related-weak') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('97d45942-8367-5e4e-9b46-1dd4a3baf908', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'competency', 'AI4K12 4-D-i.K-2, K-2, objective', 'Demonstrate some ways that intelligent agents don''t understand things the way people do.', '12ea2223-9fd7-58f2-9b4c-aa2c3f4c7ac3', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-4-d-i-k-2-lo","human_coding_scheme":"4-D-i.K-2.LO","kind":"LO","band":"K-2","definition":"Demonstrate some ways that intelligent agents don''t understand things the way people do.","alignment_state":"aligned","aligned_stages":[{"stage_id":"6f04ee30-2be3-537b-9d0e-b339d9fed79c","stage":"I2:K-2 Living Things Act to Meet Their Needs","relation":"related","strength":"weak","why":"The stage''s third indicator has children see that acting to meet a need does not require thinking as a person does. The item has them show ways intelligent agents do not understand as people do. Both separate action from human-style understanding.","sense_differs":"The stage applies this to animals acting on their own needs. AI4K12 applies it to programs designed by people. An ''agent'' in AI4K12 has goals set by a designer.","adjacent_band":false}],"citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"cross-domain","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role)
VALUES ('371fce26-d1f3-439b-95df-0a0e38b8a824', '6f04ee30-2be3-537b-9d0e-b339d9fed79c', '97d45942-8367-5e4e-9b46-1dd4a3baf908', 'related-weak') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('ada7003d-1e14-5415-a0da-91e22f61203d', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'competency', 'AI4K12 5-A-i.3-5, 3-5, objective', 'Evaluate how an AI technology can have different effects on different groups of people.', '97b0db8e-f789-5be3-80e5-f0d39b62fc12', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-5-a-i-3-5-lo","human_coding_scheme":"5-A-i.3-5.LO","kind":"LO","band":"3-5","definition":"Evaluate how an AI technology can have different effects on different groups of people.","alignment_state":"gap","aligned_stages":[],"gap_note":"How an AI technology affects different groups differently. I1:3-5 compares two communities and could add one technology and its different effects on each.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"cross-domain","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('ebff84d2-be31-5d6b-a90e-b08925bad4fb', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'competency', 'AI4K12 5-A-i.9-12, 9-12, objective', 'Explain how use of AI systems has led to disparate impacts on different groups.', '97b0db8e-f789-5be3-80e5-f0d39b62fc12', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-5-a-i-9-12-lo","human_coding_scheme":"5-A-i.9-12.LO","kind":"LO","band":"9-12","definition":"Explain how use of AI systems has led to disparate impacts on different groups.","alignment_state":"gap","aligned_stages":[],"gap_note":"Unequal effects of AI on groups. Unmet once the I2:9-12 match is dropped. The recommendation algorithm case in I2:9-12 could grow a question about who is affected differently.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"cross-domain","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('b02d8219-aae7-5c7e-8961-b7dce75f5567', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'competency', 'AI4K12 5-A-ii.6-8, 6-8, understanding', 'Accountability in AI systems means designers and decision makers take responsibility for the system''s actions. Respect for privacy means the system does not act in ways that violate people''s privacy rights.', '305867ac-2d58-51ac-9ec9-b8ac8672ee1d', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-5-a-ii-6-8-eu","human_coding_scheme":"5-A-ii.6-8.EU","kind":"EU","band":"6-8","definition":"Accountability in AI systems means designers and decision makers take responsibility for the system''s actions. Respect for privacy means the system does not act in ways that violate people''s privacy rights.","alignment_state":"gap","aligned_stages":[],"gap_note":"Accountability and privacy as design criteria. Institutions at I1:6-8 (stable rules and the arrangements that apply them) could cover accountability as a rule-based structure.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"cross-domain","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('54340f83-b98f-52e7-8c2f-623887f98dc7', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'competency', 'AI4K12 5-A-iii.6-8, 6-8, understanding', 'AI systems need to align with the norms and values of the groups they aim to serve. Developers of AI systems need to understand that values vary across cultures.', 'c6cbe914-64cf-5f55-a126-3033de3f1da9', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-5-a-iii-6-8-eu","human_coding_scheme":"5-A-iii.6-8.EU","kind":"EU","band":"6-8","definition":"AI systems need to align with the norms and values of the groups they aim to serve. Developers of AI systems need to understand that values vary across cultures.","alignment_state":"aligned","aligned_stages":[{"stage_id":"ad0173a4-5c64-5d05-96ac-2b61810c4153","stage":"I1:6-8 Culture as Transmitted, Institutions as Stabilizing Structures","relation":"related","strength":"weak","why":"The stage separates norms from institutions and treats culture as transmitted practice. The item says AI must fit the norms and values of the groups it serves. Norms are the shared topic. The stage has no content on values across cultures or on AI design.","sense_differs":"In the stage, norms are informal expectations that students tell apart from institutions. In AI4K12, norms and values are requirements a designer must learn about, and ''values'' means what stakeholders want.","adjacent_band":false}],"citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"cross-domain","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role)
VALUES ('371fce26-d1f3-439b-95df-0a0e38b8a824', 'ad0173a4-5c64-5d05-96ac-2b61810c4153', '54340f83-b98f-52e7-8c2f-623887f98dc7', 'related-weak') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('7acc44e4-9963-5e02-9c6c-0477db4c773c', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'competency', 'AI4K12 5-B-i.9-12, 9-12, understanding', 'Some new AI technologies will pose challenges for cultural norms and expectations that society must identify and wrestle with.', 'e47bf3ee-533b-5b58-a09d-6afa34c2b12a', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-5-b-i-9-12-eu","human_coding_scheme":"5-B-i.9-12.EU","kind":"EU","band":"9-12","definition":"Some new AI technologies will pose challenges for cultural norms and expectations that society must identify and wrestle with.","alignment_state":"aligned","aligned_stages":[{"stage_id":"e820dc2d-9317-57d1-8475-22a701fc486a","stage":"I1:9-12 Collective Intelligence, Distributed Cognition, and Coevolving Technology","relation":"related","strength":"weak","why":"The stage has students explain how technology and cultural selection shape an information environment such as a social media platform. The item says new AI technologies challenge cultural norms and expectations. A platform case could serve both.","sense_differs":"AI4K12 asks which norms are challenged and what debates follow. The stage asks for mechanisms: how a group-level outcome emerges and how a platform and its users shape each other.","adjacent_band":false}],"citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"cross-domain","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role)
VALUES ('371fce26-d1f3-439b-95df-0a0e38b8a824', 'e820dc2d-9317-57d1-8475-22a701fc486a', '7acc44e4-9963-5e02-9c6c-0477db4c773c', 'related-weak') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('15ff6616-a0e3-5d04-ad09-9f75eadec019', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'competency', 'AI4K12 5-B-i.K-2, K-2, objective', 'Identify devices in daily life that use AI technologies.', 'e47bf3ee-533b-5b58-a09d-6afa34c2b12a', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-5-b-i-k-2-lo","human_coding_scheme":"5-B-i.K-2.LO","kind":"LO","band":"K-2","definition":"Identify devices in daily life that use AI technologies.","alignment_state":"gap","aligned_stages":[],"gap_note":"Identify devices in daily life that use AI. I1:K-2 has Technology as a primary concept and asks for tools people use. Adding AI devices among the tools would cover it.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"cross-domain","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('5e49c238-f2bc-5ff5-8554-e7a29c77425c', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'competency', 'AI4K12 5-B-ii.3-5, 3-5, understanding', 'Current deepfakes have detectable flaws, but as the technology improves it will undermine our trust in digital media.', '0394cfa5-88f0-5e6b-8f08-f3f1693cb2c0', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-5-b-ii-3-5-eu","human_coding_scheme":"5-B-ii.3-5.EU","kind":"EU","band":"3-5","definition":"Current deepfakes have detectable flaws, but as the technology improves it will undermine our trust in digital media.","alignment_state":"gap","aligned_stages":[],"gap_note":"Deepfakes undermine trust in digital media. Information (culture sense: sources need checking) and Knowledge could carry a stage on checking sources.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"cross-domain","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('f42b12a6-ed49-5994-90e5-e47e718fb1f5', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'competency', 'AI4K12 5-B-ii.9-12, 9-12, objective', 'Identify areas where it is appropriate to regulate use of AI technologies and evaluate regulations that have been proposed.', '0394cfa5-88f0-5e6b-8f08-f3f1693cb2c0', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-5-b-ii-9-12-lo","human_coding_scheme":"5-B-ii.9-12.LO","kind":"LO","band":"9-12","definition":"Identify areas where it is appropriate to regulate use of AI technologies and evaluate regulations that have been proposed.","alignment_state":"gap","aligned_stages":[],"gap_note":"Deciding where to regulate AI. Institutions and Norms (I1:6-8) lead into a 9-12 stage on how formal rules are made and enforced.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"cross-domain","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('cf5a7bf8-ae31-5702-b43b-7df8959ee322', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'competency', 'AI4K12 5-C-i.6-8, 6-8, objective', 'Compare the changes AI is bringing to society with those of previous industrial revolutions.', '97d509a4-68ca-5318-af82-933ac8c8f82b', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-5-c-i-6-8-lo","human_coding_scheme":"5-C-i.6-8.LO","kind":"LO","band":"6-8","definition":"Compare the changes AI is bringing to society with those of previous industrial revolutions.","alignment_state":"gap","aligned_stages":[],"gap_note":"Comparing AI-driven change with earlier industrial revolutions. Technology, Innovation and Niche Construction (I1:9-12) could host a historical comparison of how technologies reshaped societies.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"cross-domain","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('b830d677-138e-5876-81e9-a2bfcbf650a6', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'competency', 'AI4K12 5-C-ii.6-8, 6-8, understanding', 'Cultures change as new technologies are adopted, and as a result some types of jobs are reduced and new types of jobs appear.', '7799c335-872d-5d2a-945c-215f11436c6e', '{"level":"ai4k12","source_vocabulary":"AI4K12","competencybase_id":"OE-COMPETENCY-ai4k12-5-c-ii-6-8-eu","human_coding_scheme":"5-C-ii.6-8.EU","kind":"EU","band":"6-8","definition":"Cultures change as new technologies are adopted, and as a result some types of jobs are reduced and new types of jobs appear.","alignment_state":"gap","aligned_stages":[],"gap_note":"Cultures change as technologies are adopted, and jobs shift. Unmet once the I1:6-8 match is dropped. Technology and Innovation in a 6-8 stage could cover it.","citation":"AI4K12 Initiative (2020-2022). Five Big Ideas in Artificial Intelligence, Grade Band Progression Charts. AAAI and CSTA, NSF DRL-1846073. CC BY-NC-SA 4.0. https://ai4k12.org/gradeband-progression-charts/","proposed_on":"2026-10-26","focus":"cross-domain","draft_note":"AI-drafted on 2026-10-26 by comparing the stages and concepts of the space with the AI4K12 grade band progression charts in CompetencyBase. No subject-matter expert has reviewed it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('ai4k12_alignment', '[{"competencybase_id":"OE-COMPETENCY-ai4k12-2-a-i","human_coding_scheme":"2-A-i","relation":"broader","why":"Representation here spans mental, cultural, educational and computational stand-ins. AI4K12 covers the last two ends: maps, symbols, trees, graphs and feature vectors. Its rows say nothing about mental representation."},{"competencybase_id":"OE-COMPETENCY-ai4k12-2-a-ii","human_coding_scheme":"2-A-ii","relation":"broader","why":"Representation here spans mental, cultural, educational and computational stand-ins. AI4K12 covers the last two ends: maps, symbols, trees, graphs and feature vectors. Its rows say nothing about mental representation."},{"competencybase_id":"OE-COMPETENCY-ai4k12-2-a-iii","human_coding_scheme":"2-A-iii","relation":"broader","why":"Representation here spans mental, cultural, educational and computational stand-ins. AI4K12 covers the last two ends: maps, symbols, trees, graphs and feature vectors. Its rows say nothing about mental representation."},{"competencybase_id":"OE-COMPETENCY-ai4k12-2-a-iv","human_coding_scheme":"2-A-iv","relation":"broader","why":"Representation here spans mental, cultural, educational and computational stand-ins. AI4K12 covers the last two ends: maps, symbols, trees, graphs and feature vectors. Its rows say nothing about mental representation."}]'::jsonb) WHERE id = 'fe387dcf-751c-59e6-9fa2-8fcc6abecea3';
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('ai4k12_alignment', '[{"competencybase_id":"OE-COMPETENCY-ai4k12-2-a-i","human_coding_scheme":"2-A-i","relation":"broader","why":"The education sense of Abstraction runs from drawing a map to describing a game board by its essential parts. AI4K12 row 2-A-i follows the same progression, from a map to a game board to a schema."}]'::jsonb) WHERE id = 'cb98e497-14c8-58c1-b14d-0467b037a8da';
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('ai4k12_alignment', '[{"competencybase_id":"OE-COMPETENCY-ai4k12-3-a-iii","human_coding_scheme":"3-A-iii","relation":"broader","why":"The AI sense of Model is a runnable description whose numbers were set from data. The AI4K12 rows on training a model, and on training versus using one, cover that sense. The scientific, cultural and cognitive senses have no row."},{"competencybase_id":"OE-COMPETENCY-ai4k12-3-a-iv","human_coding_scheme":"3-A-iv","relation":"broader","why":"The AI sense of Model is a runnable description whose numbers were set from data. The AI4K12 rows on training a model, and on training versus using one, cover that sense. The scientific, cultural and cognitive senses have no row."}]'::jsonb) WHERE id = '4507e96a-c6ac-5bcd-a258-1b83d33dbda3';
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('ai4k12_alignment', '[{"competencybase_id":"OE-COMPETENCY-ai4k12-3-a-i","human_coding_scheme":"3-A-i","relation":"broader","why":"Learning here spans cognition, biology, culture, education and machine learning. AI4K12 rows on humans versus machines, finding patterns and learning from experience cover the machine sense and its contrast with people."},{"competencybase_id":"OE-COMPETENCY-ai4k12-3-a-ii","human_coding_scheme":"3-A-ii","relation":"broader","why":"Learning here spans cognition, biology, culture, education and machine learning. AI4K12 rows on humans versus machines, finding patterns and learning from experience cover the machine sense and its contrast with people."},{"competencybase_id":"OE-COMPETENCY-ai4k12-3-a-vi","human_coding_scheme":"3-A-vi","relation":"broader","why":"Learning here spans cognition, biology, culture, education and machine learning. AI4K12 rows on humans versus machines, finding patterns and learning from experience cover the machine sense and its contrast with people."}]'::jsonb) WHERE id = '241ac4b1-00b3-517c-b3b5-10029f1efdc6';
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('ai4k12_alignment', '[{"competencybase_id":"OE-COMPETENCY-ai4k12-2-b-i","human_coding_scheme":"2-B-i","relation":"broader","why":"Search here has senses in computing, cognition, biology (foraging) and education. AI4K12 rows on state spaces and combinatorial search cover the computing sense only."},{"competencybase_id":"OE-COMPETENCY-ai4k12-2-b-ii","human_coding_scheme":"2-B-ii","relation":"broader","why":"Search here has senses in computing, cognition, biology (foraging) and education. AI4K12 rows on state spaces and combinatorial search cover the computing sense only."}]'::jsonb) WHERE id = 'c7c91feb-25f2-5996-aa6e-ddaa87585741';
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('ai4k12_alignment', '[{"competencybase_id":"OE-COMPETENCY-ai4k12-2-c-ii","human_coding_scheme":"2-C-ii","relation":"broader","why":"Algorithm here is a fixed series of steps, with senses in computation, education and technology. AI4K12 row 2-C-ii covers reasoning algorithms for classification and search, which is the computation sense."}]'::jsonb) WHERE id = '6100cc68-c0eb-5f67-823e-5f5c4c200b9f';
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('ai4k12_alignment', '[{"competencybase_id":"OE-COMPETENCY-ai4k12-3-b-ii","human_coding_scheme":"3-B-ii","relation":"broader","why":"The AI sense of Feedback is a training loop that compares output with a target or reward and adjusts numbers. AI4K12 rows on weight adjustment and on reinforcement signals cover it. The body-regulation and classroom senses have no row."},{"competencybase_id":"OE-COMPETENCY-ai4k12-3-a-vi","human_coding_scheme":"3-A-vi","relation":"broader","why":"The AI sense of Feedback is a training loop that compares output with a target or reward and adjusts numbers. AI4K12 rows on weight adjustment and on reinforcement signals cover it. The body-regulation and classroom senses have no row."}]'::jsonb) WHERE id = 'b8b2412c-6f27-54f8-b612-4c595d3e9059';
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('ai4k12_alignment', '[{"competencybase_id":"OE-COMPETENCY-ai4k12-3-a-vi","human_coding_scheme":"3-A-vi","relation":"broader","why":"The AI sense of Incentive is a reward signal that a learning program collects more of. AI4K12 row 3-A-vi covers learning from a reinforcement signal. Prices, grades and animal payoffs have no row."}]'::jsonb) WHERE id = 'd74633cc-737d-5760-9c98-28c9381c401f';
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('ai4k12_alignment', '[{"competencybase_id":"OE-COMPETENCY-ai4k12-1-a-iii","human_coding_scheme":"1-A-iii","relation":"related","why":"Information here is a pattern a receiver can use. AI4K12 covers how measurements are encoded as numbers and how perception extracts meaning from sensory signals. Neither row mentions uncertainty or bits."},{"competencybase_id":"OE-COMPETENCY-ai4k12-1-b-i","human_coding_scheme":"1-B-i","relation":"related","why":"Information here is a pattern a receiver can use. AI4K12 covers how measurements are encoded as numbers and how perception extracts meaning from sensory signals. Neither row mentions uncertainty or bits."}]'::jsonb) WHERE id = '6c5398e6-801c-55f9-9732-a018ba999e6b';
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('ai4k12_alignment', '[{"competencybase_id":"OE-COMPETENCY-ai4k12-4-a-i","human_coding_scheme":"4-A-i","relation":"related","why":"Communication here links sender, signal, shared code and receiver. AI4K12 rows on the structure and ambiguity of language cover the code in the human case and where computers struggle with it."},{"competencybase_id":"OE-COMPETENCY-ai4k12-4-a-ii","human_coding_scheme":"4-A-ii","relation":"related","why":"Communication here links sender, signal, shared code and receiver. AI4K12 rows on the structure and ambiguity of language cover the code in the human case and where computers struggle with it."}]'::jsonb) WHERE id = '301b8eed-edd6-5c71-91df-5219467c24fb';
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('ai4k12_alignment', '[{"competencybase_id":"OE-COMPETENCY-ai4k12-4-b-i","human_coding_scheme":"4-B-i","relation":"related","why":"Intuitive Theories are folk physics, folk biology and folk psychology formed without instruction. AI4K12 row 4-B-i lists naive physics and folk psychology as knowledge a computer would need. Folk biology and development are absent."}]'::jsonb) WHERE id = 'ce917c30-aaf6-59a9-b20a-36ecebf5b68f';
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('ai4k12_alignment', '[{"competencybase_id":"OE-COMPETENCY-ai4k12-4-b-i","human_coding_scheme":"4-B-i","relation":"related","why":"Theory of Mind is representing another''s goals and beliefs. AI4K12 row 4-B-i lists folk psychology as knowledge a computer would need. Row 4-C-i covers recognizing feelings, which the concept does not include, so it is left out. False-belief tasks have no row."},{"competencybase_id":"OE-COMPETENCY-ai4k12-4-c-i","human_coding_scheme":"4-C-i","relation":"related","why":"Theory of Mind is representing another''s goals and beliefs. AI4K12 row 4-B-i lists folk psychology as knowledge a computer would need. Row 4-C-i covers recognizing feelings, which the concept does not include, so it is left out. False-belief tasks have no row."}]'::jsonb) WHERE id = 'e6f78871-2017-55c6-8739-9a9c3a249315';
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('ai4k12_alignment', '[{"competencybase_id":"OE-COMPETENCY-ai4k12-4-d-i","human_coding_scheme":"4-D-i","relation":"related","why":"Agency here is sensing a setting and responding flexibly toward aims. AI4K12 row 4-D-i asks whether machines understand or are conscious. Row 1-B-i, on perception, covers only the sensing half, so it is left out. Organism agency has no row."},{"competencybase_id":"OE-COMPETENCY-ai4k12-1-b-i","human_coding_scheme":"1-B-i","relation":"related","why":"Agency here is sensing a setting and responding flexibly toward aims. AI4K12 row 4-D-i asks whether machines understand or are conscious. Row 1-B-i, on perception, covers only the sensing half, so it is left out. Organism agency has no row."}]'::jsonb) WHERE id = '993c989a-79d2-5262-b20f-9636504623cd';
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('ai4k12_alignment', '[{"competencybase_id":"OE-COMPETENCY-ai4k12-1-c-i","human_coding_scheme":"1-C-i","relation":"broader","why":"The AI sense of Knowledge is a store of statements a program searches. AI4K12 rows on domain knowledge and on schemas in knowledge graphs cover it. Knowledge held by people and groups has no row."},{"competencybase_id":"OE-COMPETENCY-ai4k12-2-a-iii","human_coding_scheme":"2-A-iii","relation":"broader","why":"The AI sense of Knowledge is a store of statements a program searches. AI4K12 rows on domain knowledge and on schemas in knowledge graphs cover it. Knowledge held by people and groups has no row."}]'::jsonb) WHERE id = 'b9faf219-7d7f-5791-abca-c738d6130497';
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('ai4k12_alignment', '[{"competencybase_id":"OE-COMPETENCY-ai4k12-5-b-i","human_coding_scheme":"5-B-i","relation":"related","why":"Technology here covers tools made and adopted in every domain. AI4K12 rows on AI in daily life and on AI''s effects on sectors of society treat one family of tools and what follows from using it. They do not define technology."},{"competencybase_id":"OE-COMPETENCY-ai4k12-5-c-i","human_coding_scheme":"5-C-i","relation":"related","why":"Technology here covers tools made and adopted in every domain. AI4K12 rows on AI in daily life and on AI''s effects on sectors of society treat one family of tools and what follows from using it. They do not define technology."}]'::jsonb) WHERE id = '1d89ba05-d574-53ea-aaa9-c513d9125e96';
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('ai4k12_alignment', '[{"competencybase_id":"OE-COMPETENCY-ai4k12-5-b-i","human_coding_scheme":"5-B-i","relation":"related","why":"The AI sense of Culture is machine culture, a proposed extension. AI4K12 row 5-B-i covers AI in daily life and the debates it raises. The shared ground is that AI products shape what people see and make. The row uses ''culture'' for a society''s norms."}]'::jsonb) WHERE id = '8c0525a4-0873-52c6-a097-8915714a33ae';
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('ai4k12_alignment', '[{"competencybase_id":"OE-COMPETENCY-ai4k12-5-a-iii","human_coding_scheme":"5-A-iii","relation":"related","why":"Norms are shared expectations upheld by a group''s approval. AI4K12 row 5-A-iii asks designers to learn the norms and values of the groups an AI system serves. Norms as a topic in themselves have no row."}]'::jsonb) WHERE id = 'c529c772-66e2-5915-93f8-adedafc7732d';
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('ai4k12_alignment', '[{"competencybase_id":"OE-COMPETENCY-ai4k12-5-b-ii","human_coding_scheme":"5-B-ii","relation":"related","why":"Institutions are stable rules with arrangements that apply them. AI4K12 row 5-B-ii asks students to judge which uses of AI deserve regulation, and regulation is an institution. The row stays on AI."}]'::jsonb) WHERE id = '4ebf512e-ba71-59c4-8e93-e03007a9d829';
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('ai4k12_alignment', '[{"competencybase_id":"OE-COMPETENCY-ai4k12-2-a-ii","human_coding_scheme":"2-A-ii","relation":"related","why":"Descent is drawn as a branching tree, and borrowing between lines turns it into a network. AI4K12 rows on trees and graphs teach those two diagram forms as data structures. The match covers the diagram form only. Ancestry has no row."},{"competencybase_id":"OE-COMPETENCY-ai4k12-2-a-iii","human_coding_scheme":"2-A-iii","relation":"related","why":"Descent is drawn as a branching tree, and borrowing between lines turns it into a network. AI4K12 rows on trees and graphs teach those two diagram forms as data structures. The match covers the diagram form only. Ancestry has no row."}]'::jsonb) WHERE id = 'e0a89c95-8625-539f-93ef-ac864737144a';
UPDATE projects SET introduction = introduction || '

Alignment with AI4K12. This space is aligned with the AI4K12 progression charts (Five Big Ideas in Artificial Intelligence, held in CompetencyBase) with a cross-domain focus: all five Big Ideas can be reached, and each alignment says what the reading across biology, culture, technology, education, AI and computation, and cognition adds. 13 of 16 stages align with at least one AI4K12 item of the same grade band (0 strong, 2 partial and 11 weak matches), and 29 AI4K12 items inside the focus have no stage and are listed as gaps in the taxonomy. A match was made only where a teacher could defend it. The alignments are proposed. AI drafted them and no subject expert has reviewed them.' WHERE id = '371fce26-d1f3-439b-95df-0a0e38b8a824' AND introduction NOT LIKE '%Alignment with AI4K12. This space%';

